  ('hsk1-14-5', 1, 80, '学', '14.5 Подурок 5', '14.5 Podlekcja 5', '14.5 Sub-lesson 5', 14, 'Урок 14', 'Lekcja 14', 'Lesson 14'),
  ('hsk1-15-1', 1, 81, '学', '15.1 Подурок 1', '15.1 Podlekcja 1', '15.1 Sub-lesson 1', 15, 'Урок 15', 'Lekcja 15', 'Lesson 15'),
  ('hsk1-15-2', 1, 82, '学', '15.2 Подурок 2', '15.2 Podlekcja 2', '15.2 Sub-lesson 2', 15, 'Урок 15', 'Lekcja 15', 'Lesson 15'),
  ('hsk1-15-3', 1, 83, '学', '15.3 Подурок 3', '15.3 Podlekcja 3', '15.3 Sub-lesson 3', 15, 'Урок 15', 'Lekcja 15', 'Lesson 15'),
  ('hsk1-15-4', 1, 84, '学', '15.4 Подурок 4', '15.4 Podlekcja 4', '15.4 Sub-lesson 4', 15, 'Урок 15', 'Lekcja 15', 'Lesson 15'),
  ('hsk1-15-5', 1, 85, '学', '15.5 Подурок 5', '15.5 Podlekcja 5', '15.5 Sub-lesson 5', 15, 'Урок 15', 'Lekcja 15', 'Lesson 15');

insert into public.lesson_slides (lesson_id, position, kind, payload)
select l.id, v.pos, v.kind, v.payload::jsonb
from (values
  ('hsk1-01-1', 1, 'fact', '{"emoji":"🗣️","title":"«Ты хороший» — значит «привет»","text":"Китайское 你好 буквально звучит как «ты — хороший». Никакого «здравствуй» в корне нет: приветствие — это просто пожелание добра. А в иероглифе 好 живёт целая история: 女 «женщина» рядом с 子 «ребёнок» — для китайцев это и есть «хорошо». Вежливое 您 устроено ещё красивее: 你 «ты» с сердцем 心 под ним."}'),
  ('hsk1-01-1', 2, 'words', '{"title":"Четыре первых слова","items":[{"hanzi":"你","pinyin":"nǐ","m":"ты","emoji":"🫵","ex":{"zh":"你好！","py":"Nǐ hǎo!","m":"Привет!"}},{"hanzi":"好","pinyin":"hǎo","m":"хороший, хорошо","emoji":"👍","ex":{"zh":"你好！","py":"Nǐ hǎo!","m":"Привет! (ты — хороший)"}},{"hanzi":"您","pinyin":"nín","m":"Вы (вежливо)","emoji":"🎩","ex":{"zh":"老师，您好！","py":"Lǎoshī, nín hǎo!","m":"Здравствуйте, учитель!"}},{"hanzi":"我","pinyin":"wǒ","m":"я","emoji":"🙋","ex":{"zh":"我好。","py":"Wǒ hǎo.","m":"Я в порядке."}}]}'),
  ('hsk1-01-1', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → иероглиф","items":[{"emoji":"🫵","options":["你","我","您"],"correct":0,"explain":"Палец, указывающий на собеседника — «ты»."},{"emoji":"🙋","options":["你","我","好"],"correct":1,"explain":"Человек поднял руку: «я»."},{"emoji":"🎩","options":["您","我","你"],"correct":0,"explain":"Шляпа-цилиндр — знак уважения: 您."},{"emoji":"👍","options":["您","好","我"],"correct":1,"explain":"Большой палец вверх — 好."}]}'),
  ('hsk1-01-1', 4, 'theory', '{"title":"你 или 您: кому что говорить","blocks":[{"t":"table","head":["Слово","Тон вежливости","Кому"],"rows":[["你 nǐ","обычный","друзья, ровесники, дети"],["您 nín","уважительный","учитель, старший, клиент, начальник"],["我 wǒ","нейтральный","всегда «я»"]]},{"t":"p","text":"Сравните: в 您 под 你 добавлено сердце 心 — «ты, но от всего сердца». Отличить 你 и 您 на слух легко: у 您 в конце «-n», а не «-i»."},{"t":"tip","text":"Не уверены, кого перед вами видите? Выбирайте 您: за лишнюю вежливость на вас не обидятся."}]}'),
  ('hsk1-01-1', 5, 'quiz', '{"title":"Мини-тест: кому какое слово","qs":[{"q":"Вы встретили своего профессора. Что скажете?","options":["您好！","你好！","我好！"],"correct":0,"explain":"Старшему и преподавателю — 您."},{"q":"好 состоит из «женщины» 女 и «ребёнка» 子.","tf":true},{"q":"您 — это просто другое написание 你 без разницы в вежливости.","tf":false,"explain":"Нет, 您 — уважительная форма."}]}'),
  ('hsk1-01-1', 6, 'game', '{"type":"match","title":"Соедините иероглиф и смысл","pairs":[["你","ты"],["我","я"],["您","Вы (вежливо)"],["好","хороший"],["你好","привет"]]}'),
  ('hsk1-01-1', 7, 'game', '{"type":"listen","title":"Кого мы слышим: ты, я или Вы?","items":[{"say":"你好","options":["nǐ hǎo","nín hǎo","wǒ hǎo"],"correct":0},{"say":"您好","options":["nǐ hǎo","nín hǎo","wǒ hǎo"],"correct":1,"explain":"Слышите «-n» на конце первого слога — значит вежливое 您."},{"say":"我","options":["nǐ","nín","wǒ"],"correct":2},{"say":"你","options":["nǐ","nín","wǒ"],"correct":0},{"say":"您","options":["nǐ","nín","wǒ"],"correct":1}]}'),
  ('hsk1-01-1', 8, 'theory', '{"title":"Скрытая фишка: 你好 звучит иначе, чем пишется","blocks":[{"t":"p","text":"Два третьих тона подряд не произносят. Первый превращается во второй, поэтому вживую вы услышите ní hǎo, хотя пишется nǐ hǎo. Тоны вы уже знаете с Уровня 0 — теперь слушайте, как они работают в живой речи."},{"t":"ex","zh":"你好！","py":"Nǐ hǎo! (звучит: ní hǎo)","m":"Привет!","say":"你好"},{"t":"ex","zh":"您好！","py":"Nín hǎo!","m":"Здравствуйте!","say":"您好"}]}'),
  ('hsk1-01-1', 9, 'game', '{"type":"build","title":"Соберите приветствие","items":[{"answer":["你","好"],"hint":"Скажите другу: «Привет!»"},{"answer":["您","好"],"hint":"Скажите директору: «Здравствуйте!»"}]}'),
  ('hsk1-01-1', 10, 'write', '{"title":"Пропись: нарисуйте по чертам","items":[{"hanzi":"你","pinyin":"nǐ","m":"ты","hint":"亻 слева, 尔 справа"},{"hanzi":"好","pinyin":"hǎo","m":"хороший","hint":"女 слева, 子 справа"},{"hanzi":"您","pinyin":"nín","m":"Вы","hint":"сверху 你, снизу 心"},{"hanzi":"我","pinyin":"wǒ","m":"я","hint":"сначала горизонталь, потом откидная 丿 и точка"}]}'),
  ('hsk1-01-1', 11, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как переводится 我?","options":["ты","я","Вы","хороший"],"correct":1},{"q":"Какой иероглиф означает «Вы» (вежливо)?","options":["你","我","您","好"],"correct":2},{"q":"Как на самом деле звучит 你好 в быстрой речи?","options":["nǐ hǎo","ní hǎo","nì hǎo"],"correct":1,"explain":"Правило двух третьих тонов."},{"q":"Приветствие 你好 буквально значит «ты хороший».","tf":true},{"q":"Что скрыто под 你 в иероглифе 您?","options":["女","心","子"],"correct":1}]}'),
  ('hsk1-01-2', 1, 'fact', '{"emoji":"🧩","title":"Китайская грамматика без окончаний","text":"Хорошие новости: слова не склоняются, не спрягаются и не имеют рода. Чтобы задать вопрос, достаточно добавить один слог в конец. Чтобы сказать «не», ставим 不 перед словом. Чтобы получить «мы / вы / они», приклеиваем 们. Три маленьких слова, и вы уже строите реальные фразы."}'),
  ('hsk1-01-2', 2, 'words', '{"title":"Два слова для примеров","items":[{"hanzi":"老师","pinyin":"lǎoshī","m":"учитель","emoji":"👩‍🏫","ex":{"zh":"老师好！","py":"Lǎoshī hǎo!","m":"Здравствуйте, учитель!"}},{"hanzi":"再见","pinyin":"zàijiàn","m":"до свидания","emoji":"👋","ex":{"zh":"老师再见！","py":"Lǎoshī zàijiàn!","m":"До свидания, учитель!"}}]}'),
  ('hsk1-01-2', 3, 'theory', '{"title":"Вопрос с 吗","blocks":[{"t":"p","text":"Утверждение + 吗 = вопрос «да или нет?». Порядок слов не меняется, интонацию тоже менять не надо. 吗 звучит коротко и без тона."},{"t":"table","head":["Утверждение","Вопрос"],"rows":[["你好。 Nǐ hǎo.","你好吗？ Nǐ hǎo ma?  Как дела?"],["您好。 Nín hǎo.","您好吗？ Nín hǎo ma?  Как Ваши дела?"]]},{"t":"ex","zh":"你好吗？","py":"Nǐ hǎo ma?","m":"Как ты? Как дела?","say":"你好吗"},{"t":"tip","text":"吗 всегда в самом конце. Ставить его в середину нельзя."}]}'),
  ('hsk1-01-2', 4, 'quiz', '{"title":"Мини-тест: вопрос","qs":[{"q":"Как спросить «Как Ваши дела?» у учителя?","options":["您好吗？","吗您好？","你吗好？"],"correct":0},{"q":"吗 можно поставить в начало предложения.","tf":false,"explain":"Только в конец."}]}'),
  ('hsk1-01-2', 5, 'game', '{"type":"build","title":"Сборка вопросов","items":[{"answer":["你","好","吗"],"hint":"Спросите друга: «Как дела?»"},{"answer":["您","好","吗"],"hint":"Спросите учителя: «Как Ваши дела?»"},{"answer":["老师","好","吗"],"hint":"Спросите: «Учитель в порядке?»"}]}'),
  ('hsk1-01-2', 6, 'theory', '{"title":"Отрицание с 不","blocks":[{"t":"p","text":"不 ставится перед глаголом или прилагательным и значит «не». Но у него есть секрет: перед четвёртым тоном он меняется на второй."},{"t":"table","head":["Что идёт после 不","Как читаем 不","Пример"],"rows":[["1, 2, 3 тон","bù (4 тон)","不好 bù hǎo  нехорошо"],["4 тон","bú (2 тон)","不见 bú jiàn  не увидеться"]]},{"t":"ex","zh":"我不好。","py":"Wǒ bù hǎo.","m":"Мне нехорошо.","say":"我不好"},{"t":"tip","text":"Пишется всегда одинаково 不, меняется только звучание. Пиньинь отражает изменение: bú."}]}'),
  ('hsk1-01-2', 7, 'game', '{"type":"listen","title":"Слышим тон 不 и 吗","items":[{"say":"不好","options":["bù hǎo","bú hǎo"],"correct":0,"explain":"После 3 тона 不 остаётся bù."},{"say":"不见","options":["bù jiàn","bú jiàn"],"correct":1,"explain":"После 4 тона 不 становится bú."},{"say":"你好吗","options":["nǐ hǎo ma","nǐ hǎo mā"],"correct":0,"explain":"吗 безударный."},{"say":"老师再见","options":["lǎoshī zàijiàn","lǎoshī zǎijiǎn"],"correct":0}]}'),
  ('hsk1-01-2', 8, 'quiz', '{"title":"Мини-тест: тон 不","qs":[{"q":"Как читается 不 в слове 不见?","options":["bù","bú","bǔ"],"correct":1},{"q":"Как читается 不 в слове 不好?","options":["bù","bú"],"correct":0},{"q":"На письме 不 меняется на другой иероглиф перед 4 тоном.","tf":false,"explain":"Меняется только произношение."}]}'),
  ('hsk1-01-2', 9, 'theory', '{"title":"Множественное число с 们","blocks":[{"t":"p","text":"们 приклеивается к людям: 我们 «мы», 你们 «вы (много)», 老师们 «учителя». Слог безударный. К вежливому 您 его не добавляют: у 您 нет формы «Вы (много)»."},{"t":"table","head":["Единственное","Множественное"],"rows":[["我 wǒ","我们 wǒmen  мы"],["你 nǐ","你们 nǐmen  вы"],["老师 lǎoshī","老师们 lǎoshīmen  учителя"]]},{"t":"ex","zh":"你们好！","py":"Nǐmen hǎo!","m":"Здравствуйте, ребята!","say":"你们好"}]}'),
  ('hsk1-01-2', 10, 'game', '{"type":"match","title":"Роли маленьких слов","pairs":[["吗","вопрос «да/нет» в конце фразы"],["不","отрицание «не»"],["们","множественное число людей"],["再见","до свидания"],["老师","учитель"]]}'),
  ('hsk1-01-2', 11, 'game', '{"type":"build","title":"Соберите фразы","items":[{"answer":["你们","好"],"hint":"Поприветствуйте класс: «Здравствуйте, ребята!»"},{"answer":["老师","再见"],"hint":"Попрощайтесь: «До свидания, учитель!»"},{"answer":["我","不","好"],"hint":"Скажите: «Мне нехорошо.»"}]}'),
  ('hsk1-01-2', 12, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «мы»?","options":["我们","我吗","我不"],"correct":0},{"q":"Какая форма неправильная?","options":["你们","我们","您们"],"correct":2,"explain":"У 您 нет множественного числа с 们."},{"q":"吗 произносится без тона.","tf":true},{"q":"Какой тон у 不 в 不见?","options":["4","2","3"],"correct":1},{"q":"Как спросить у класса «Как дела?»","options":["你们好吗？","你好吗们？","吗你们好？"],"correct":0}]}'),
  ('hsk1-01-3', 1, 'fact', '{"emoji":"🙇","title":"Вежливость на двух полюсах","text":"В китайском все вежливые формулы работают парами: вам сказали «спасибо» — вы отвечаете 不客气, то есть «не будьте гостем» (не церемоньтесь). Вам сказали «извините» — отвечаете 没关系: «нет связи» (ничего страшного). Выучите пары, и вы не ошибётесь в диалоге."}'),
  ('hsk1-01-3', 2, 'words', '{"title":"Четыре формулы вежливости","items":[{"hanzi":"谢谢","pinyin":"xièxie","m":"спасибо","emoji":"🙏","ex":{"zh":"谢谢你！","py":"Xièxie nǐ!","m":"Спасибо тебе!"}},{"hanzi":"不客气","pinyin":"bú kèqi","m":"не за что","emoji":"😊","ex":{"zh":"不客气！","py":"Bú kèqi!","m":"Не за что!"}},{"hanzi":"对不起","pinyin":"duìbuqǐ","m":"извините","emoji":"🙇","ex":{"zh":"对不起，老师！","py":"Duìbuqǐ, lǎoshī!","m":"Извините, учитель!"}},{"hanzi":"没关系","pinyin":"méi guānxi","m":"ничего страшного","emoji":"🤝","ex":{"zh":"没关系！","py":"Méi guānxi!","m":"Ничего страшного!"}}]}'),
  ('hsk1-01-3', 3, 'game', '{"type":"listen","title":"Аудио-практикум: формулы","items":[{"say":"谢谢","options":["xièxie","xiéxié","xièxiè"],"correct":0,"explain":"Второй слог безударный."},{"say":"不客气","options":["bù kèqi","bú kèqi"],"correct":1,"explain":"不 перед 4 тоном (客 kè) → bú."},{"say":"对不起","options":["duìbuqǐ","duìbùqǐ","dùbuqǐ"],"correct":0},{"say":"没关系","options":["méi guānxi","mèi guānxi","měi guānxi"],"correct":0},{"say":"再见","options":["zàijiàn","zǎijiàn","zàijiān"],"correct":0}]}'),
  ('hsk1-01-3', 4, 'game', '{"type":"tone_visualizer","initialTone":4,"title":"Тренажёр голоса: повторите «xiè» (4 тон) и сравните кривую"}'),
  ('hsk1-01-3', 5, 'game', '{"type":"match","title":"Реплика и ответ","pairs":[["谢谢！","不客气！"],["对不起！","没关系！"],["你好！","你好！"],["再见！","再见！"]]}'),
  ('hsk1-01-3', 6, 'theory', '{"title":"Реплика → ответ: не перепутайте","blocks":[{"t":"table","head":["Вам говорят","Вы отвечаете"],"rows":[["谢谢！ Xièxie!","不客气！ Bú kèqi!"],["对不起！ Duìbuqǐ!","没关系！ Méi guānxi!"]]},{"t":"p","text":"Перепутать пары — самая частая ошибка новичков. Отвечать на 对不起 словами 不客气 — как на «простите, что наступил на ногу» ответить «пожалуйста»."},{"t":"tip","text":"谢谢 можно усилить: 谢谢你 (другу), 谢谢您 (старшему), 谢谢老师 (учителю)."}]}'),
  ('hsk1-01-3', 7, 'quiz', '{"title":"Мини-тест: пары","qs":[{"q":"Вам сказали 谢谢！ Что ответите?","options":["没关系！","不客气！","对不起！"],"correct":1},{"q":"Вам сказали 对不起！ Что ответите?","options":["不客气！","没关系！","谢谢！"],"correct":1},{"q":"На 谢谢 отвечают 没关系.","tf":false,"explain":"Нужно 不客气."}]}'),
  ('hsk1-01-3', 8, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → фраза","items":[{"emoji":"🙏","options":["谢谢","对不起","再见"],"correct":0},{"emoji":"🙇","options":["不客气","对不起","你好"],"correct":1},{"emoji":"🤝","options":["没关系","谢谢","您"],"correct":0},{"emoji":"😊","options":["不客气","没关系","老师"],"correct":0}]}'),
  ('hsk1-01-3', 9, 'game', '{"type":"build","title":"Соберите реплику","items":[{"answer":["谢谢","你"],"hint":"Поблагодарите друга"},{"answer":["谢谢","您"],"hint":"Поблагодарите профессора"},{"answer":["对不起","老师"],"hint":"Извинитесь перед учителем"},{"answer":["没","关系"],"hint":"Скажите: «Ничего страшного!»"}]}'),
  ('hsk1-01-3', 10, 'game', '{"type":"listen","title":"Кому и что сказано?","items":[{"say":"谢谢你","options":["xièxie nǐ","xièxie nín"],"correct":0},{"say":"谢谢您","options":["xièxie nǐ","xièxie nín"],"correct":1},{"say":"对不起，老师","options":["duìbuqǐ, lǎoshī","méi guānxi, lǎoshī"],"correct":0},{"say":"不客气","options":["bú kèqi","méi guānxi"],"correct":0},{"say":"没关系","options":["bú kèqi","méi guānxi"],"correct":1}]}'),
  ('hsk1-01-3', 11, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как переводится 对不起?","options":["спасибо","извините","до свидания","не за что"],"correct":1},{"q":"Что значит 没关系?","options":["ничего страшного","здравствуйте","я тебя люблю"],"correct":0},{"q":"不客气 читается bú kèqi.","tf":true,"explain":"Сандхи: 不 перед 4 тоном."},{"q":"Как вежливо поблагодарить учителя?","options":["谢谢你！","谢谢您！","对不起！"],"correct":1},{"q":"Реплика 谢谢你，再见！ значит…","options":["Спасибо тебе, до свидания!","Извини, привет!","Не за что, пока!"],"correct":0}]}'),
  ('hsk1-01-4', 1, 'fact', '{"emoji":"🏫","title":"Как студент опоздал и всё исправил","text":"В китайском университете перед занятием принято поздороваться с преподавателем первым и поклониться чуть-чуть головой. Опоздали? Скажите 对不起. Нет, 谢谢 здесь не поможет. В диалоге ниже сразу видно, как слова главы работают вместе."}'),
  ('hsk1-01-4', 2, 'text', '{"title":"Урок только что начался","lines":[{"zh":"学生：老师，您好！","py":"Xuésheng: Lǎoshī, nín hǎo!","m":"Студент: Здравствуйте, учитель!"},{"zh":"老师：你们好！","py":"Lǎoshī: Nǐmen hǎo!","m":"Учитель: Здравствуйте, ребята!"},{"zh":"学生：老师，对不起！","py":"Xuésheng: Lǎoshī, duìbuqǐ!","m":"Студент: Извините, учитель!"},{"zh":"老师：没关系。你好吗？","py":"Lǎoshī: Méi guānxi. Nǐ hǎo ma?","m":"Учитель: Ничего страшного. Как ты?"},{"zh":"学生：我好。谢谢您！","py":"Xuésheng: Wǒ hǎo. Xièxie nín!","m":"Студент: Я в порядке. Спасибо Вам!"},{"zh":"老师：不客气。","py":"Lǎoshī: Bú kèqi.","m":"Учитель: Не за что."},{"zh":"学生：老师再见！","py":"Xuésheng: Lǎoshī zàijiàn!","m":"Студент: До свидания, учитель!"},{"zh":"老师：再见！","py":"Lǎoshī: Zàijiàn!","m":"Учитель: До свидания!"}],"qs":[{"q":"Почему студент говорит 您, а не 你?","options":["Он говорит с преподавателем","Он говорит с другом","Это опечатка"],"correct":0},{"q":"Студент извиняется перед учителем.","tf":true},{"q":"Вставьте слово: 老师：______。你好吗？ (после извинения)","options":["没关系","不客气","再见"],"correct":0},{"q":"Учитель отвечает 没关系 на 谢谢您.","tf":false,"explain":"На 谢谢 он отвечает 不客气."},{"q":"Что значит 你们好 в начале урока?","options":["Привет всем (группе)","Привет одному студенту","Как дела?"],"correct":0},{"q":"Какая реплика закрывает диалог?","options":["再见！","你好！","对不起！"],"correct":0},{"q":"Найдите вопрос в диалоге:","options":["你好吗？","我好。","不客气。"],"correct":0}]}'),
  ('hsk1-01-4', 3, 'game', '{"type":"match","title":"Какую функцию выполняет реплика?","pairs":[["老师，您好！","Приветствие учителю"],["老师，对不起！","Извинение"],["谢谢您！","Благодарность"],["不客气。","Ответ на благодарность"],["老师再见！","Прощание"]]}'),
  ('hsk1-01-4', 4, 'theory', '{"title":"Разбор: кто кому как говорит","blocks":[{"t":"table","head":["Ситуация","Что сказать","Что НЕ говорить"],"rows":[["Здороваетесь с преподавателем","老师，您好！","老师，你好！"],["Здороваетесь с группой","你们好！","您们好！"],["Вам извинились","没关系。","不客气。"]]},{"t":"tip","text":"Иностранец, который говорит 您 учителю и 你 другу, звучит как человек, который понимает культуру."}]}'),
  ('hsk1-01-4', 5, 'game', '{"type":"bughunt","title":"Китайский детектив: найдите ошибку","cases":[{"buggyText":"老师，你好！","context":"Студент здоровается с профессором","options":["老师，您好！","老师，你们好！","老师，好吗？"],"correct":0,"explain":"Старшему — 您."},{"buggyText":"对不起！ — 不客气！","context":"Ответ на извинение","options":["没关系！","谢谢！","再见！"],"correct":0,"explain":"На 对不起 отвечаем 没关系."},{"buggyText":"谢谢！ — 没关系！","context":"Ответ на благодарность","options":["不客气！","对不起！","老师好！"],"correct":0,"explain":"На 谢谢 отвечаем 不客气."},{"buggyText":"您们好！","context":"Приветствие группе профессоров","options":["你们好！","您好们！","好吗们！"],"correct":0,"explain":"У 您 нет формы с 们."}]}'),
  ('hsk1-01-4', 6, 'game', '{"type":"listen","title":"Слышим реплики из диалога","items":[{"say":"老师，您好！","options":["lǎoshī, nín hǎo","lǎoshī, nǐ hǎo"],"correct":0},{"say":"没关系。","options":["méi guānxi","bú kèqi"],"correct":0},{"say":"你们好！","options":["nǐmen hǎo","nǐ hǎo"],"correct":0},{"say":"谢谢您！","options":["xièxie nín","xièxie nǐ"],"correct":0}]}'),
  ('hsk1-01-4', 7, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как переводится 老师？","options":["учитель","студент","друг"],"correct":0},{"q":"Вставьте слово: 谢谢您！ — ______。","options":["不客气","对不起","没关系"],"correct":0},{"q":"Диалог показывает, что 您 и 你 взаимозаменяемы.","tf":false,"explain":"Нет, регистр зависит от собеседника."},{"q":"Какая последовательность логична для опоздавшего студента?","options":["对不起 → 没关系","没关系 → 对不起","再见 → 你好"],"correct":0}]}'),
  ('hsk1-01-5', 1, 'fact', '{"emoji":"🎨","title":"Сегодня вы не зубрите, а создаёте","text":"Иероглифы — это конструктор. Вы соберёте 好 и 您 из частей, напишете сообщение в WeChat, составите открытку учителю и исправите чужой диалог. Всё из слов главы 1."}'),
  ('hsk1-01-5', 2, 'game', '{"type":"radical_puzzle","hanzi":"好","correctRadicals":["女","子"],"title":"Пазл: соберите 好 из частей"}'),
  ('hsk1-01-5', 3, 'game', '{"type":"radical_build","title":"Конструктор: соберите знак из блоков","items":[{"targetHanzi":"你","radicals":["亻","尔","木"],"correctOrder":["亻","尔"],"explain":"亻 «человек» + 尔."},{"targetHanzi":"您","radicals":["你","心","女"],"correctOrder":["你","心"],"explain":"你 сверху, 心 «сердце» снизу."}]}'),
  ('hsk1-01-5', 4, 'game', '{"type":"chatsim","title":"WeChat: ответьте Ли Мину","messages":[{"speaker":"Ли Мин","text":"你好！","pinyin":"Nǐ hǎo!","translation":"Привет!","options":["你好！","再见！","不客气！"],"correct":0,"explain":"Отвечаем приветствием."},{"speaker":"Ли Мин","text":"你好吗？","pinyin":"Nǐ hǎo ma?","translation":"Как дела?","options":["我好。谢谢！","没关系。","对不起！"],"correct":0,"explain":"Мы в порядке и благодарим за вопрос."},{"speaker":"Ли Мин","text":"对不起，老师！","pinyin":"Duìbuqǐ, lǎoshī!","translation":"Извините, учитель!","options":["没关系。","不客气。","再见。"],"correct":0,"explain":"Ответ на извинение."},{"speaker":"Ли Мин","text":"谢谢您！","pinyin":"Xièxie nín!","translation":"Спасибо Вам!","options":["不客气。","对不起。","你好。"],"correct":0,"explain":"Ответ на благодарность."}]}'),
  ('hsk1-01-5', 5, 'game', '{"type":"build","title":"Мастерская открыток","items":[{"target":"(Открытка учителю)","answer":["老师","谢谢","您"],"hint":"Напишите открытку: «Учитель, спасибо Вам!»"},{"target":"(Открытка классу)","answer":["你们","好"],"hint":"Подпишите плакат: «Здравствуйте, все!»"},{"target":"(Записка другу)","answer":["谢谢","你","再见"],"hint":"Записка: «Спасибо, пока!»"}]}'),
  ('hsk1-01-5', 6, 'theory', '{"title":"Идея для открытки","blocks":[{"t":"p","text":"Возьмите любую пару: реплика + ответ. Нарисуйте двух героев, над ними напишите 您好 и 你们好, внизу добавьте 谢谢 и 不客气. Получилась открытка для урока."},{"t":"ex","zh":"老师，谢谢您！","py":"Lǎoshī, xièxie nín!","m":"Учитель, спасибо Вам!","say":"老师，谢谢您"},{"t":"tip","text":"Сочиняйте как можно больше реплик с известными словами: так появляется чувство языка."}]}'),
  ('hsk1-01-5', 7, 'game', '{"type":"match","title":"Собрать знак из частей","pairs":[["女 + 子","好"],["你 + 心","您"],["亻 + 门","们"],["我 + 们","我们"]]}'),
  ('hsk1-01-5', 8, 'game', '{"type":"bughunt","title":"Исправьте чужие реплики","cases":[{"buggyText":"我好吗你？","context":"Спросить «Как твои дела?»","options":["你好吗？","吗你好？","好你吗？"],"correct":0,"explain":"吗 в конце, порядок слов как в утверждении."},{"buggyText":"我们 好 您们","context":"Составить приветствие для группы","options":["你们好！","您们好！","们你好！"],"correct":0}]}'),
  ('hsk1-01-5', 9, 'write', '{"title":"Пропись: суффикс и местоимение","items":[{"hanzi":"们","pinyin":"men","m":"суффикс множественного числа","hint":"亻 «человек» + 门 «дверь»"},{"hanzi":"我","pinyin":"wǒ","m":"я","hint":"Следите за точкой и откидной чертой"}]}'),
  ('hsk1-01-5', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Ваш друг сказал 对不起. Лучший ответ?","options":["没关系！","不客气！","再见！"],"correct":0},{"q":"Вы пишете записку одногруппникам: «Здравствуйте, ребята!»","options":["你们好！","您好！","你好吗们！"],"correct":0},{"q":"Из каких частей состоит 您?","options":["你 + 心","女 + 子","亻 + 门"],"correct":0},{"q":"Для открытки учителю можно написать 您好.","tf":true}]}'),
  ('hsk1-01-6', 1, 'fact', '{"emoji":"🏁","title":"Экзамен главы 1","text":"Здесь собрано всё: слух, иероглифы, грамматика и вежливость. Если не набрано проходных баллов, следующая глава не откроется, и это нормально: вернитесь к урокам и пройдите ещё раз."}'),
  ('hsk1-01-6', 2, 'game', '{"type":"listen","title":"Аудирование","items":[{"say":"你好","options":["nǐ hǎo","nín hǎo","nǐmen hǎo"],"correct":0},{"say":"您好","options":["nǐ hǎo","nín hǎo","nǐmen hǎo"],"correct":1},{"say":"你们好","options":["nǐ hǎo","nín hǎo","nǐmen hǎo"],"correct":2},{"say":"谢谢","options":["xièxie","duìbuqǐ","zàijiàn"],"correct":0},{"say":"不客气","options":["bú kèqi","méi guānxi","bù hǎo"],"correct":0},{"say":"对不起","options":["duìbuqǐ","xièxie","zàijiàn"],"correct":0},{"say":"没关系","options":["méi guānxi","bú kèqi","lǎoshī"],"correct":0},{"say":"再见","options":["zàijiàn","xièxie","nǐ hǎo"],"correct":0}]}'),
  ('hsk1-01-6', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🫵","options":["你","我","您"],"correct":0},{"emoji":"🎩","options":["您","我","们"],"correct":0},{"emoji":"👩‍🏫","options":["学生","老师","朋友"],"correct":1},{"emoji":"👋","options":["再见","谢谢","不客气"],"correct":0}]}'),
  ('hsk1-01-6', 4, 'game', '{"type":"match","title":"Слова главы","pairs":[["你","ты"],["您","Вы (вежливо)"],["我","я"],["老师","учитель"],["吗","вопросительная частица"],["们","суффикс мн. числа"],["对不起","извините"],["没关系","ничего страшного"]]}'),
  ('hsk1-01-6', 5, 'quiz', '{"title":"Экзаменационные вопросы","qs":[{"q":"Как читается 你好 в быстрой речи?","options":["ní hǎo","nǐ hǎo","nì hǎo"],"correct":0},{"q":"Как читается 不 в 不客气?","options":["bú","bù","bǔ"],"correct":0},{"q":"Как спросить «Как дела?»","options":["你好吗？","吗你好？","你吗好？"],"correct":0},{"q":"Как сказать «мы»?","options":["我们","我吗","我不"],"correct":0},{"q":"Форма 您们 допустима в учебном китайском.","tf":false},{"q":"Ответ на 谢谢 — 不客气.","tf":true},{"q":"Ответ на 对不起:","options":["没关系","不客气","谢谢"],"correct":0},{"q":"Как поприветствовать профессора?","options":["老师，您好！","老师，你好！","老师，你们好！"],"correct":0},{"q":"Что значит 再见?","options":["до свидания","извините","спасибо"],"correct":0},{"q":"Какой тон у 吗?","options":["нейтральный","1","4"],"correct":0}]}'),
  ('hsk1-01-6', 6, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["你","好","吗"],"hint":"«Как дела?»"},{"answer":["谢谢","您"],"hint":"«Спасибо Вам!»"},{"answer":["老师","再见"],"hint":"«До свидания, учитель!»"},{"answer":["我","不","好"],"hint":"«Мне нехорошо.»"}]}'),
  ('hsk1-01-6', 7, 'game', '{"type":"bughunt","title":"Найдите ошибку","cases":[{"buggyText":"老师，你好！","context":"Приветствие преподавателю","options":["老师，您好！","老师，你们好！","老师，好吗？"],"correct":0},{"buggyText":"对不起！ — 谢谢！","context":"Ответ на извинение","options":["没关系！","不客气！","再见！"],"correct":0},{"buggyText":"您们好！","context":"Группе профессоров","options":["你们好！","您好们！","好您！"],"correct":0}]}'),
  ('hsk1-01-6', 8, 'game', '{"type":"chatsim","title":"Мини-чат","messages":[{"speaker":"Ли Мин","text":"老师，您好！","pinyin":"Lǎoshī, nín hǎo!","translation":"Учитель, здравствуйте!","options":["你们好！","再见！","没关系。"],"correct":0},{"speaker":"Ли Мин","text":"对不起！","pinyin":"Duìbuqǐ!","translation":"Извините!","options":["没关系。","不客气。","你好。"],"correct":0},{"speaker":"Ли Мин","text":"谢谢！","pinyin":"Xièxie!","translation":"Спасибо!","options":["不客气。","对不起。","吗？"],"correct":0}]}'),
  ('hsk1-01-6', 9, 'write', '{"title":"Пропись по памяти","items":[{"hanzi":"你","pinyin":"nǐ","m":"ты","hint":"亻 + 尔"},{"hanzi":"好","pinyin":"hǎo","m":"хороший","hint":"女 + 子"},{"hanzi":"您","pinyin":"nín","m":"Вы","hint":"你 + 心"}]}'),
  ('hsk1-01-6', 10, 'recall', '{"words":[{"hanzi":"你","pinyin":"nǐ","m":"ты"},{"hanzi":"好","pinyin":"hǎo","m":"хороший"},{"hanzi":"您","pinyin":"nín","m":"Вы (вежливо)"},{"hanzi":"我","pinyin":"wǒ","m":"я"},{"hanzi":"老师","pinyin":"lǎoshī","m":"учитель"},{"hanzi":"再见","pinyin":"zàijiàn","m":"до свидания"},{"hanzi":"谢谢","pinyin":"xièxie","m":"спасибо"},{"hanzi":"不客气","pinyin":"bú kèqi","m":"не за что"},{"hanzi":"对不起","pinyin":"duìbuqǐ","m":"извините"},{"hanzi":"没关系","pinyin":"méi guānxi","m":"ничего страшного"}],"tf":[{"zh":"您们好","py":"nínmen hǎo","m":"Здравствуйте, господа","ok":false,"explain":"У 您 нет формы с 们."},{"zh":"你们好","py":"nǐmen hǎo","m":"Здравствуйте, ребята","ok":true},{"zh":"谢谢。— 没关系。","py":"xièxie. méi guānxi.","m":"Спасибо. — Ничего страшного.","ok":false,"explain":"Нужно 不客气."}],"sentences":[{"zh":"你好吗？","tokens":["你","好","吗"],"m":"Как дела?"},{"zh":"老师，谢谢您！","tokens":["老师","谢谢","您"],"m":"Учитель, спасибо Вам!"},{"zh":"老师再见！","tokens":["老师","再见"],"m":"До свидания, учитель!"}]}'),
  ('hsk1-02-1', 1, 'fact', '{"emoji":"🏷️","title":"Имя в темноте","text":"В знаке 名 «имя» спрятаны 夕 «вечер» и 口 «рот»: когда вечером темно и лица не видно, человека окликают по имени. Знак 叫 «звать» тоже держит 口. А ещё у китайцев фамилия стоит перед именем: 李明 — это фамилия Ли и имя Мин."}'),
  ('hsk1-02-1', 2, 'words', '{"title":"Четыре слова для знакомства","items":[{"hanzi":"叫","pinyin":"jiào","m":"звать, называться","emoji":"🗣️","ex":{"zh":"我叫安娜。","py":"Wǒ jiào Ānnà.","m":"Меня зовут Анна."}},{"hanzi":"名字","pinyin":"míngzi","m":"имя","emoji":"🏷️","ex":{"zh":"你叫什么名字？","py":"Nǐ jiào shénme míngzi?","m":"Как тебя зовут?"}},{"hanzi":"什么","pinyin":"shénme","m":"что, какой","emoji":"❓","ex":{"zh":"你叫什么？","py":"Nǐ jiào shénme?","m":"Как тебя зовут?"}},{"hanzi":"是","pinyin":"shì","m":"быть, являться","emoji":"✅","ex":{"zh":"我是安娜。","py":"Wǒ shì Ānnà.","m":"Я Анна."}}]}'),
  ('hsk1-02-1', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🏷️","options":["名字","什么","是"],"correct":0},{"emoji":"❓","options":["叫","什么","是"],"correct":1},{"emoji":"✅","options":["是","叫","名字"],"correct":0},{"emoji":"🗣️","options":["叫","是","什么"],"correct":0}]}'),
  ('hsk1-02-1', 4, 'theory', '{"title":"Три способа представиться","blocks":[{"t":"table","head":["Что хотите сказать","Фраза"],"rows":[["Меня зовут…","我叫 + имя"],["Я — …","我是 + имя"],["Как тебя зовут?","你叫什么名字？"]]},{"t":"ex","zh":"我叫安娜。","py":"Wǒ jiào Ānnà.","m":"Меня зовут Анна.","say":"我叫安娜"},{"t":"ex","zh":"你叫什么名字？","py":"Nǐ jiào shénme míngzi?","m":"Как тебя зовут?","say":"你叫什么名字"},{"t":"tip","text":"Иностранные имена пишутся иероглифами «по звучанию»: Анна — 安娜 Ānnà."}]}'),
  ('hsk1-02-1', 5, 'quiz', '{"title":"Мини-тест: имя","qs":[{"q":"Как спросить «Как тебя зовут?»","options":["你叫什么名字？","你是名字吗？","什么叫你名字？"],"correct":0},{"q":"В китайском имени сначала идёт фамилия.","tf":true},{"q":"什么 — это слово «спасибо».","tf":false,"explain":"什么 значит «что, какой»."}]}'),
  ('hsk1-02-1', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["叫","звать, называться"],["名字","имя"],["什么","что, какой"],["是","быть, являться"],["我叫安娜","Меня зовут Анна"]]}'),
  ('hsk1-02-1', 7, 'game', '{"type":"listen","title":"Слушаем знакомство","items":[{"say":"你叫什么名字","options":["nǐ jiào shénme míngzi","nǐ shì shénme míngzi","nǐ jiào míngzi"],"correct":0},{"say":"我叫安娜","options":["wǒ jiào Ānnà","wǒ shì Ānnà","nǐ jiào Ānnà"],"correct":0},{"say":"什么","options":["shénme","shíme","shénma"],"correct":0},{"say":"名字","options":["míngzi","míngzì","mínzi"],"correct":0},{"say":"是","options":["shì","shí","shǐ"],"correct":0}]}'),
  ('hsk1-02-1', 8, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","叫","安娜"],"hint":"Скажите: «Меня зовут Анна.»"},{"answer":["你","叫","什么","名字"],"hint":"Спросите: «Как тебя зовут?»"},{"answer":["我","是","老师"],"hint":"Скажите: «Я учитель.»"}]}'),
  ('hsk1-02-1', 9, 'write', '{"title":"Пропись по чертам","items":[{"hanzi":"叫","pinyin":"jiào","m":"звать","hint":"слева 口, справа 丩"},{"hanzi":"是","pinyin":"shì","m":"быть","hint":"сверху 日, снизу 疋"},{"hanzi":"名","pinyin":"míng","m":"имя","hint":"сверху 夕, снизу 口"}]}'),
  ('hsk1-02-1', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 名字?","options":["имя","учитель","спасибо","вежливо"],"correct":0},{"q":"Что скрыто в знаке 名?","options":["夕 и 口","女 и 子","亻 и 尔"],"correct":0},{"q":"Как сказать «Меня зовут Анна»?","options":["我叫安娜。","我名字叫是安娜。","叫我安娜是。"],"correct":0},{"q":"我是安娜 тоже значит «Я Анна».","tf":true},{"q":"Какое слово спрашивает «что?»","options":["什么","名字","叫"],"correct":0}]}'),
  ('hsk1-02-2', 1, 'fact', '{"emoji":"⚙️","title":"Китайский вопрос не меняет порядок слов","text":"По-русски мы говорим «Как тебя зовут?», переставляя слова. В китайском вопросительное слово просто садится на место ответа: «ты зовёшься что?» — 你叫什么？ Ответ встанет туда же: 我叫安娜. Никаких перестановок, никаких 吗 в таких вопросах."}'),
  ('hsk1-02-2', 2, 'words', '{"title":"Он и она","items":[{"hanzi":"他","pinyin":"tā","m":"он","emoji":"👨","ex":{"zh":"他是老师。","py":"Tā shì lǎoshī.","m":"Он учитель."}},{"hanzi":"她","pinyin":"tā","m":"она","emoji":"👩","ex":{"zh":"她叫安娜。","py":"Tā jiào Ānnà.","m":"Её зовут Анна."}}]}'),
  ('hsk1-02-2', 3, 'theory', '{"title":"Схема «А 是 В»","blocks":[{"t":"table","head":["Фраза","Пиньинь","Перевод"],"rows":[["我是老师。","Wǒ shì lǎoshī.","Я учитель."],["他是老师。","Tā shì lǎoshī.","Он учитель."],["她不是老师。","Tā bú shì lǎoshī.","Она не учитель."]]},{"t":"p","text":"Отрицание: 不 ставится перед 是. Вспомните правило: 是 — четвёртый тон, поэтому 不 превращается в bú."},{"t":"tip","text":"Глагол 是 не изменяется: ни по лицам, ни по числам, ни по временам."}]}'),
  ('hsk1-02-2', 4, 'game', '{"type":"build","title":"Соберите предложение с 是","items":[{"answer":["他","是","老师"],"hint":"«Он учитель.»"},{"answer":["她","不","是","老师"],"hint":"«Она не учитель.»"},{"answer":["我","不","是","老师"],"hint":"«Я не учитель.»"}]}'),
  ('hsk1-02-2', 5, 'quiz', '{"title":"Мини-тест: 是 и 不","qs":[{"q":"Как правильно: «Она не учитель»?","options":["她不是老师。","她是不老师。","她老师不是。"],"correct":0},{"q":"不 перед 是 читается bú.","tf":true}]}'),
  ('hsk1-02-2', 6, 'theory', '{"title":"Он и она: тот же звук, разные знаки","blocks":[{"t":"p","text":"Оба местоимения читаются tā. Различает их ключ слева: 亻 «человек» у 他 и 女 «женщина» у 她. Справа у обоих 也. На слух вы разберёте по контексту."},{"t":"table","head":["Знак","Левая часть","Смысл"],"rows":[["他","亻","он"],["她","女","она"]]}]}'),
  ('hsk1-02-2', 7, 'theory', '{"title":"Вопрос с 什么 без перестановки","blocks":[{"t":"table","head":["Вопрос","Ответ"],"rows":[["你叫什么名字？","我叫李明。"],["她叫什么？","她叫安娜。"],["他是什么人？","他是学生。"]]},{"t":"tip","text":"Если в вопросе есть 什么, добавлять 吗 не нужно."}]}'),
  ('hsk1-02-2', 8, 'quiz', '{"title":"Мини-тест: 什么","qs":[{"q":"Что нужно заменить в ответе 我叫李明 на вопросительное слово?","options":["李明 → 什么","我 → 什么","叫 → 什么"],"correct":0},{"q":"К вопросу 你叫什么名字？ нужно добавить 吗.","tf":false,"explain":"С вопросительным словом 吗 не ставится."},{"q":"Как спросить «Как её зовут?»","options":["她叫什么名字？","她吗叫名字？","什么她叫？"],"correct":0}]}'),
  ('hsk1-02-2', 9, 'game', '{"type":"match","title":"Роли слов","pairs":[["他","он"],["她","она"],["不是","не является"],["什么","что, какой"],["吗","вопрос «да / нет»"]]}'),
  ('hsk1-02-2', 10, 'game', '{"type":"listen","title":"Аудио: он, она, вопрос","items":[{"say":"他是老师。","options":["tā shì lǎoshī","tā bú shì lǎoshī","tā shì lǎoshǐ"],"correct":0},{"say":"她不是老师。","options":["tā shì lǎoshī","tā bú shì lǎoshī","tā bù shì lǎoshī"],"correct":1,"explain":"不 перед 4 тоном — bú."},{"say":"你叫什么名字","options":["nǐ jiào shénme míngzi","nǐ jiào shénme míngzì"],"correct":0},{"say":"她叫安娜","options":["tā jiào Ānnà","nǐ jiào Ānnà"],"correct":0}]}'),
  ('hsk1-02-2', 11, 'game', '{"type":"bughunt","title":"Китайский детектив: поймайте ошибку","cases":[{"buggyText":"我叫是安娜。","context":"Представиться: «Меня зовут Анна»","options":["我叫安娜。","我是叫安娜。","我名字安娜叫。"],"correct":0,"explain":"Вместе 叫 и 是 не ставим."},{"buggyText":"你叫名字什么？","context":"Спросить имя","options":["你叫什么名字？","什么你叫名字？","你什么叫名字？"],"correct":0,"explain":"Вопросительное слово — на место ответа."},{"buggyText":"她是不老师。","context":"Сказать «Она не учитель»","options":["她不是老师。","她老师不是。","她是老师不。"],"correct":0}]}'),
  ('hsk1-02-2', 12, 'quiz', '{"title":"Итог урока","qs":[{"q":"Какой иероглиф означает «он»?","options":["他","她","你"],"correct":0},{"q":"Что значит 她?","options":["она","он","ты"],"correct":0},{"q":"Как читается 她不是学生? (на что менять 不)","options":["bú shì","bù shì","bǔ shì"],"correct":0},{"q":"他 и 她 читаются одинаково.","tf":true},{"q":"Как спросить «Что это за имя?» — какое слово нужно?","options":["什么","是","他"],"correct":0}]}'),
  ('hsk1-02-3', 1, 'fact', '{"emoji":"🤝","title":"Фраза, которую вы скажете сотни раз","text":"很高兴认识你 — «очень рад с вами познакомиться». Слово 认识 значит и «знать человека», и «познакомиться». 高兴 дословно «высокий подъём»: настроение взлетает. А слово 很 в китайском служит «усилителем» и одновременно «связкой» перед прилагательным."}'),
  ('hsk1-02-3', 2, 'words', '{"title":"Три слова для знакомства","items":[{"hanzi":"认识","pinyin":"rènshi","m":"знать, познакомиться","emoji":"🤝","ex":{"zh":"我认识她。","py":"Wǒ rènshi tā.","m":"Я её знаю."}},{"hanzi":"高兴","pinyin":"gāoxìng","m":"радостный, рад","emoji":"😄","ex":{"zh":"很高兴！","py":"Hěn gāoxìng!","m":"Очень рад!"}},{"hanzi":"很","pinyin":"hěn","m":"очень","emoji":"💯","ex":{"zh":"我很好。","py":"Wǒ hěn hǎo.","m":"Я в порядке."}}]}'),
  ('hsk1-02-3', 3, 'game', '{"type":"listen","title":"Слушаем: новые слова","items":[{"say":"认识","options":["rènshi","rénshì","rènshí"],"correct":0,"explain":"Второй слог безударный."},{"say":"高兴","options":["gāoxìng","gāoxīng","gáoxìng"],"correct":0},{"say":"很","options":["hěn","hén","hèn"],"correct":0},{"say":"很高兴认识你","options":["hěn gāoxìng rènshi nǐ","hěn gāoxìng rènshì nǐ"],"correct":0},{"say":"我认识她","options":["wǒ rènshi tā","wǒ rènshi nǐ"],"correct":0}]}'),
  ('hsk1-02-3', 4, 'game', '{"type":"tone_visualizer","initialTone":3,"title":"Тренажёр голоса: повторите «hěn» (3 тон)"}'),
  ('hsk1-02-3', 5, 'theory', '{"title":"Формула знакомства","blocks":[{"t":"table","head":["Часть","Что значит"],"rows":[["很高兴","очень рад"],["认识你","познакомиться с тобой"],["很高兴认识你","очень рад познакомиться"]]},{"t":"p","text":"很 ставится перед прилагательным: 很高兴, 很好. Без него фраза звучит как сравнение («по сравнению с кем-то»). В быстрой речи 很好 превращается в hén hǎo — два третьих тона подряд."},{"t":"tip","text":"Ответ на 很高兴认识你 — та же фраза: 我也很高兴. Слово 也 вы выучите позже, пока повторяйте 很高兴认识你."}]}'),
  ('hsk1-02-3', 6, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🤝","options":["认识","高兴","很"],"correct":0},{"emoji":"😄","options":["高兴","叫","是"],"correct":0},{"emoji":"💯","options":["很","他","她"],"correct":0}]}'),
  ('hsk1-02-3', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["认识","знать, познакомиться"],["高兴","радостный, рад"],["很","очень"],["很高兴认识你","рад познакомиться"],["我认识她","я её знаю"]]}'),
  ('hsk1-02-3', 8, 'game', '{"type":"chatsim","title":"WeChat: первое знакомство","messages":[{"speaker":"Ли Мин","text":"你好！我叫李明。","pinyin":"Nǐ hǎo! Wǒ jiào Lǐ Míng.","translation":"Привет! Меня зовут Ли Мин.","options":["你好！我叫安娜。","再见！","对不起！"],"correct":0,"explain":"Здороваемся и называем имя."},{"speaker":"Ли Мин","text":"很高兴认识你！","pinyin":"Hěn gāoxìng rènshi nǐ!","translation":"Очень рад знакомству!","options":["很高兴认识你！","不客气。","没关系。"],"correct":0,"explain":"Отвечаем той же фразой."},{"speaker":"Ли Мин","text":"你认识她吗？","pinyin":"Nǐ rènshi tā ma?","translation":"Ты её знаешь?","options":["认识，她是老师。","我叫她。","谢谢她。"],"correct":0,"explain":"认识 — знать человека."}]}'),
  ('hsk1-02-3', 9, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["很","高兴","认识","你"],"hint":"«Очень рад познакомиться.»"},{"answer":["我","认识","她"],"hint":"«Я её знаю.»"},{"answer":["我","很","好"],"hint":"«Я в порядке.»"}]}'),
  ('hsk1-02-3', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 认识?","options":["знать, познакомиться","радоваться","очень"],"correct":0},{"q":"Какое слово ставится перед 高兴 для усиления?","options":["很","是","吗"],"correct":0},{"q":"很高兴认识你 значит «Очень рад познакомиться».","tf":true},{"q":"Как читается 很好 в быстрой речи?","options":["hén hǎo","hěn hǎo","hèn hǎo"],"correct":0},{"q":"Как перевести 我认识他?","options":["Я его знаю.","Он знает меня.","Он рад."],"correct":0}]}'),
  ('hsk1-02-4', 1, 'fact', '{"emoji":"🎒","title":"Первый урок китайского","text":"В китайских классах ученики часто представляются по очереди. Звучит это просто: приветствие, имя, «рад познакомиться». Сегодня вы читаете такой диалог целиком и без подсказок на русском, только с опорой на уже выученные слова."}'),
  ('hsk1-02-4', 2, 'text', '{"title":"Первый день занятий","lines":[{"zh":"王老师：你们好！我叫王芳。","py":"Wáng lǎoshī: Nǐmen hǎo! Wǒ jiào Wáng Fāng.","m":"Учитель Ван: Здравствуйте! Меня зовут Ван Фан."},{"zh":"安娜：老师好！我叫安娜。","py":"Ānnà: Lǎoshī hǎo! Wǒ jiào Ānnà.","m":"Анна: Здравствуйте! Меня зовут Анна."},{"zh":"王老师：安娜，很高兴认识你。","py":"Wáng lǎoshī: Ānnà, hěn gāoxìng rènshi nǐ.","m":"Учитель Ван: Анна, очень рада познакомиться."},{"zh":"李明：老师好！我叫李明。","py":"Lǐ Míng: Lǎoshī hǎo! Wǒ jiào Lǐ Míng.","m":"Ли Мин: Здравствуйте! Меня зовут Ли Мин."},{"zh":"王老师：李明，很高兴认识你。","py":"Wáng lǎoshī: Lǐ Míng, hěn gāoxìng rènshi nǐ.","m":"Учитель Ван: Ли Мин, очень рада познакомиться."},{"zh":"李明：你叫什么名字？","py":"Lǐ Míng: Nǐ jiào shénme míngzi?","m":"Ли Мин: Как тебя зовут?"},{"zh":"安娜：我叫安娜。你好，李明！","py":"Ānnà: Wǒ jiào Ānnà. Nǐ hǎo, Lǐ Míng!","m":"Анна: Меня зовут Анна. Привет, Ли Мин!"},{"zh":"李明：你好，安娜！很高兴认识你。","py":"Lǐ Míng: Nǐ hǎo, Ānnà! Hěn gāoxìng rènshi nǐ.","m":"Ли Мин: Привет, Анна! Очень рад познакомиться."}],"qs":[{"q":"Как зовут учителя?","options":["王芳","安娜","李明"],"correct":0},{"q":"В начале диалога Анна и Ли Мин уже знакомы.","tf":false,"explain":"Они знакомятся в последних репликах."},{"q":"Вставьте слово: 安娜，很高兴___你。","options":["认识","叫","是"],"correct":0},{"q":"Кому Ли Мин задаёт вопрос 你叫什么名字？","options":["Анне","учителю","самому себе"],"correct":0},{"q":"Ли Мин говорит учителю 你好.","tf":false,"explain":"Он говорит 老师好 — уважительнее."},{"q":"Какая фраза значит «Рад познакомиться»?","options":["很高兴认识你","你叫什么名字","老师好"],"correct":0},{"q":"Что отвечает Анна на вопрос об имени?","options":["我叫安娜","我是老师","谢谢"],"correct":0}]}'),
  ('hsk1-02-4', 3, 'game', '{"type":"match","title":"Кто есть кто","pairs":[["王芳","учитель"],["安娜","первая студентка"],["李明","второй студент"],["你们好！","приветствие группе"],["很高兴认识你","формула знакомства"]]}'),
  ('hsk1-02-4', 4, 'game', '{"type":"listen","title":"Слышим реплики из диалога","items":[{"say":"我叫王芳","options":["wǒ jiào Wáng Fāng","wǒ shì Wáng Fāng"],"correct":0},{"say":"很高兴认识你","options":["hěn gāoxìng rènshi nǐ","hěn gāoxìng rènshi tā"],"correct":0},{"say":"老师好","options":["lǎoshī hǎo","lǎoshī hào"],"correct":0},{"say":"你叫什么名字","options":["nǐ jiào shénme míngzi","tā jiào shénme míngzi"],"correct":0}]}'),
  ('hsk1-02-4', 5, 'theory', '{"title":"Разбор: как правильно представиться учителю","blocks":[{"t":"table","head":["Ситуация","Фраза","Чего избегать"],"rows":[["Поздоровались с учителем","老师好！","老师，你好！"],["Назвали имя","我叫安娜。","我是叫安娜。"],["Хотите познакомиться","很高兴认识你。","我认识你很高兴。"]]}]}'),
  ('hsk1-02-4', 6, 'game', '{"type":"bughunt","title":"Китайский детектив: ошибки знакомства","cases":[{"buggyText":"老师，你叫什么名字？","context":"Студент спрашивает имя учителя","options":["老师，您叫什么名字？","老师，你们叫什么？","老师，叫吗？"],"correct":0,"explain":"Старшему говорим 您."},{"buggyText":"我叫是李明。","context":"Ли Мин представляется","options":["我叫李明。","我李明叫。","叫我是李明。"],"correct":0},{"buggyText":"很高兴你认识。","context":"Сказать «Рад познакомиться»","options":["很高兴认识你。","认识很高兴你。","高兴很认识你。"],"correct":0}]}'),
  ('hsk1-02-4', 7, 'quiz', '{"title":"Итог урока","qs":[{"q":"Какая фраза уместна для учителя?","options":["您叫什么名字？","你叫什么名字？"],"correct":0},{"q":"Как перевести 你好，李明？","options":["Привет, Ли Мин!","Как тебя зовут, Ли Мин?","До свидания, Ли Мин!"],"correct":0},{"q":"王芳 — фамилия и имя учителя.","tf":true},{"q":"Как читается 认识?","options":["rènshi","rénshí","rěnshī"],"correct":0}]}'),
  ('hsk1-02-5', 1, 'fact', '{"emoji":"🪪","title":"Визитка — китайский обычай","text":"В Китае визитку подают и принимают двумя руками, и на неё обязательно смотрят. Сегодня вы создаёте «визитки» из блоков, собираете знаки и пишете сообщения. Все слова из глав 1 и 2."}'),
  ('hsk1-02-5', 2, 'game', '{"type":"radical_puzzle","hanzi":"名","correctRadicals":["夕","口"],"title":"Пазл: соберите 名"}'),
  ('hsk1-02-5', 3, 'game', '{"type":"radical_build","title":"Сборка знаков из частей","items":[{"targetHanzi":"他","radicals":["亻","也","女"],"correctOrder":["亻","也"],"explain":"Слева 亻 «человек», справа 也."},{"targetHanzi":"她","radicals":["女","也","亻"],"correctOrder":["女","也"],"explain":"Слева 女 «женщина», справа 也."},{"targetHanzi":"叫","radicals":["口","丩","夕"],"correctOrder":["口","丩"],"explain":"Слева 口, справа 丩."}]}'),
  ('hsk1-02-5', 4, 'game', '{"type":"build","title":"Мастерская визиток","items":[{"target":"(Визитка)","answer":["我","叫","安娜"],"hint":"На визитке: «Меня зовут Анна.»"},{"target":"(Визитка)","answer":["我","是","老师"],"hint":"На визитке: «Я учитель.»"},{"target":"(Вопрос коллеге)","answer":["她","叫","什么","名字"],"hint":"Спросите: «Как её зовут?»"},{"target":"(Вопрос коллеге)","answer":["你","认识","他","吗"],"hint":"Спросите: «Ты его знаешь?»"}]}'),
  ('hsk1-02-5', 5, 'theory', '{"title":"Алгоритм знакомства из четырёх шагов","blocks":[{"t":"table","head":["Шаг","Фраза"],"rows":[["1. Приветствие","你好！ / 老师好！"],["2. Имя","我叫…"],["3. Вопрос об имени","你叫什么名字？"],["4. Радость","很高兴认识你！"]]},{"t":"tip","text":"Составьте свой диалог из четырёх шагов, используя другое имя."}]}'),
  ('hsk1-02-5', 6, 'game', '{"type":"chatsim","title":"WeChat: новое знакомство","messages":[{"speaker":"Анна","text":"你好！我叫安娜。","pinyin":"Nǐ hǎo! Wǒ jiào Ānnà.","translation":"Привет! Меня зовут Анна.","options":["你好！我叫李明。","再见！","不客气。"],"correct":0},{"speaker":"Анна","text":"你叫什么名字？","pinyin":"Nǐ jiào shénme míngzi?","translation":"Как тебя зовут?","options":["我叫李明。","我是什么。","名字叫你。"],"correct":0},{"speaker":"Анна","text":"很高兴认识你！","pinyin":"Hěn gāoxìng rènshi nǐ!","translation":"Рада познакомиться!","options":["很高兴认识你！","对不起！","没关系。"],"correct":0},{"speaker":"Анна","text":"他是谁？","pinyin":"Tā shì shéi?","translation":"Кто он? (谁 «кто» — новое слово)","options":["他叫大卫。","他是什么。","他叫什么吗？"],"correct":0,"explain":"Отвечаем по схеме «他叫…»."}]}'),
