  ('hsk1-02-5', 9, 'quiz', '{"title":"Итог урока","qs":[{"q":"Ваш новый друг сказал 很高兴认识你. Что ответите?","options":["很高兴认识你！","对不起！","再见！"],"correct":0},{"q":"Какой ключ у 她?","options":["女","亻","口"],"correct":0},{"q":"Как спросить про имя женщины?","options":["她叫什么名字？","她吗叫什么？","她是叫什么？"],"correct":0},{"q":"Визитку по китайскому обычаю подают двумя руками.","tf":true}]}'),
  ('hsk1-02-6', 1, 'fact', '{"emoji":"🏁","title":"Экзамен главы 2","text":"Проверяем слух, иероглифы, схему «А 是 В», вопросительное слово 什么 и формулы знакомства. Не набрали проходной балл — возвращайтесь к урокам и повторите слова."}'),
  ('hsk1-02-6', 2, 'game', '{"type":"listen","title":"Аудирование","items":[{"say":"我叫安娜","options":["wǒ jiào Ānnà","wǒ shì Ānnà","wǒ jiào Lǐ Míng"],"correct":0},{"say":"你叫什么名字","options":["nǐ jiào shénme míngzi","tā jiào shénme míngzi","nǐ shì shénme"],"correct":0},{"say":"她不是老师","options":["tā bú shì lǎoshī","tā bù shì lǎoshī","tā shì lǎoshī"],"correct":0},{"say":"我认识他","options":["wǒ rènshi tā","wǒ rènshi nǐ","tā rènshi wǒ"],"correct":0},{"say":"很高兴认识你","options":["hěn gāoxìng rènshi nǐ","hěn gāoxìng jiào nǐ","gāoxìng hěn rènshi"],"correct":0},{"say":"他是老师","options":["tā shì lǎoshī","tā bú shì lǎoshī"],"correct":0}]}'),
  ('hsk1-02-6', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🏷️","options":["名字","什么","高兴"],"correct":0},{"emoji":"😄","options":["高兴","认识","叫"],"correct":0},{"emoji":"👨","options":["他","她","我"],"correct":0},{"emoji":"👩","options":["他","她","你"],"correct":1}]}'),
  ('hsk1-02-6', 4, 'game', '{"type":"match","title":"Слова главы","pairs":[["叫","звать"],["名字","имя"],["什么","что, какой"],["是","быть"],["他","он"],["她","она"],["认识","знать, познакомиться"],["高兴","рад"],["很","очень"]]}'),
  ('hsk1-02-6', 5, 'quiz', '{"title":"Экзаменационные вопросы","qs":[{"q":"Как сказать «Меня зовут Анна»?","options":["我叫安娜。","我名字安娜叫。","叫我是安娜。"],"correct":0},{"q":"Как спросить «Как тебя зовут?»","options":["你叫什么名字？","你叫名字吗？","什么你叫名字？"],"correct":0},{"q":"Как читается 不 в 不是?","options":["bú","bù","bǔ"],"correct":0},{"q":"К вопросу с 什么 добавляют 吗.","tf":false},{"q":"Что значит 她?","options":["она","он","ты"],"correct":0},{"q":"Как перевести 我认识她?","options":["Я её знаю.","Она меня зовёт.","Я рада."],"correct":0},{"q":"很 ставится перед прилагательным.","tf":true},{"q":"Как читается 很好 в быстрой речи?","options":["hén hǎo","hěn hǎo","hèn hǎo"],"correct":0},{"q":"Какая реплика — ответ на 很高兴认识你?","options":["很高兴认识你！","没关系。","你叫什么？"],"correct":0},{"q":"Как сказать «Он не учитель»?","options":["他不是老师。","他老师不是。","他是不老师。"],"correct":0}]}'),
  ('hsk1-02-6', 6, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","叫","李明"],"hint":"«Меня зовут Ли Мин.»"},{"answer":["她","不","是","老师"],"hint":"«Она не учитель.»"},{"answer":["你","叫","什么","名字"],"hint":"«Как тебя зовут?»"},{"answer":["很","高兴","认识","你"],"hint":"«Очень рад познакомиться.»"}]}'),
  ('hsk1-02-6', 7, 'game', '{"type":"bughunt","title":"Найдите ошибку","cases":[{"buggyText":"老师，你叫什么名字？","context":"Вопрос учителю","options":["老师，您叫什么名字？","老师，你们叫什么？","老师，什么叫？"],"correct":0},{"buggyText":"我叫是安娜。","context":"Представиться","options":["我叫安娜。","我是叫安娜。","我安娜叫。"],"correct":0},{"buggyText":"你叫什么名字吗？","context":"Спросить имя","options":["你叫什么名字？","你叫名字什么吗？","你吗叫什么名字？"],"correct":0}]}'),
  ('hsk1-02-6', 8, 'game', '{"type":"chatsim","title":"Мини-чат","messages":[{"speaker":"Ли Мин","text":"你好！你叫什么名字？","pinyin":"Nǐ hǎo! Nǐ jiào shénme míngzi?","translation":"Привет! Как тебя зовут?","options":["我叫安娜。","我是什么。","再见！"],"correct":0},{"speaker":"Ли Мин","text":"很高兴认识你！","pinyin":"Hěn gāoxìng rènshi nǐ!","translation":"Очень рад познакомиться!","options":["很高兴认识你！","没关系。","对不起。"],"correct":0}]}'),
  ('hsk1-02-6', 9, 'write', '{"title":"Пропись по памяти","items":[{"hanzi":"叫","pinyin":"jiào","m":"звать","hint":"口 + 丩"},{"hanzi":"名","pinyin":"míng","m":"имя","hint":"夕 + 口"},{"hanzi":"他","pinyin":"tā","m":"он","hint":"亻 + 也"}]}'),
  ('hsk1-02-6', 10, 'recall', '{"words":[{"hanzi":"叫","pinyin":"jiào","m":"звать"},{"hanzi":"名字","pinyin":"míngzi","m":"имя"},{"hanzi":"什么","pinyin":"shénme","m":"что"},{"hanzi":"是","pinyin":"shì","m":"быть"},{"hanzi":"他","pinyin":"tā","m":"он"},{"hanzi":"她","pinyin":"tā","m":"она"},{"hanzi":"认识","pinyin":"rènshi","m":"знать, познакомиться"},{"hanzi":"高兴","pinyin":"gāoxìng","m":"рад"},{"hanzi":"很","pinyin":"hěn","m":"очень"},{"hanzi":"你","pinyin":"nǐ","m":"ты"},{"hanzi":"您","pinyin":"nín","m":"Вы"},{"hanzi":"谢谢","pinyin":"xièxie","m":"спасибо"}],"tf":[{"zh":"你叫什么名字吗？","py":"nǐ jiào shénme míngzi ma?","m":"Как тебя зовут?","ok":false,"explain":"С 什么 не нужно 吗."},{"zh":"她不是老师。","py":"tā bú shì lǎoshī.","m":"Она не учитель.","ok":true}],"sentences":[{"zh":"我叫安娜。","tokens":["我","叫","安娜"],"m":"Меня зовут Анна."},{"zh":"他是老师。","tokens":["他","是","老师"],"m":"Он учитель."},{"zh":"很高兴认识你。","tokens":["很","高兴","认识","你"],"m":"Очень рад познакомиться."}]}'),
  ('hsk1-03-1', 1, 'fact', '{"emoji":"🏯","title":"«Срединное государство» и «Северная столица»","text":"中国 — это 中 «середина» и 国 «страна»: китайцы издревле считали свою страну центром мира. В знаке 国 рамка 囗 охраняет 玉 «нефрит». 北京 — «северная столица» (北 «север», 京 «столица»), а у города 南京 в названии «юг». Слово 汉语 буквально «язык ханьцев» (самого многочисленного народа Китая)."}'),
  ('hsk1-03-1', 2, 'words', '{"title":"Страна и язык","items":[{"hanzi":"中国","pinyin":"Zhōngguó","m":"Китай","emoji":"🇨🇳","ex":{"zh":"我是中国人。","py":"Wǒ shì Zhōngguó rén.","m":"Я китаец."}},{"hanzi":"北京","pinyin":"Běijīng","m":"Пекин","emoji":"🏯","ex":{"zh":"他是北京人。","py":"Tā shì Běijīng rén.","m":"Он из Пекина."}},{"hanzi":"人","pinyin":"rén","m":"человек, люди","emoji":"🧑","ex":{"zh":"你是中国人吗？","py":"Nǐ shì Zhōngguó rén ma?","m":"Ты китаец?"}},{"hanzi":"汉语","pinyin":"Hànyǔ","m":"китайский язык","emoji":"📖","ex":{"zh":"汉语老师","py":"Hànyǔ lǎoshī","m":"учитель китайского"}}]}'),
  ('hsk1-03-1', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🇨🇳","options":["中国","北京","汉语"],"correct":0},{"emoji":"🏯","options":["北京","中国","人"],"correct":0},{"emoji":"🧑","options":["人","他","你"],"correct":0},{"emoji":"📖","options":["汉语","名字","老师"],"correct":0}]}'),
  ('hsk1-03-1', 4, 'theory', '{"title":"Национальность: страна + 人","blocks":[{"t":"table","head":["Страна","Человек"],"rows":[["中国 Zhōngguó","中国人 Zhōngguó rén — китаец"],["北京 Běijīng","北京人 Běijīng rén — пекинец"],["美国 Měiguó (США)","美国人 Měiguó rén"],["俄罗斯 Èluósī (Россия)","俄罗斯人 Èluósī rén"]]},{"t":"p","text":"人 — один из самых старых иероглифов: нарисован идущий человек со ссутуленной спиной. Добавьте 人 к названию страны, и получите её жителя."},{"t":"tip","text":"Названия других стран и городов пишутся иероглифами по звучанию, выучите только схему: место + 人."}]}'),
  ('hsk1-03-1', 5, 'quiz', '{"title":"Мини-тест: страна","qs":[{"q":"Как сказать «Я китаец»?","options":["我是中国人。","我中国是人。","中国我是。"],"correct":0},{"q":"北京 буквально значит «северная столица».","tf":true},{"q":"汉语 — это название страны.","tf":false,"explain":"汉语 — язык, страна — 中国."}]}'),
  ('hsk1-03-1', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["中国","Китай"],["北京","Пекин"],["人","человек, люди"],["汉语","китайский язык"],["中国人","китаец"]]}'),
  ('hsk1-03-1', 7, 'game', '{"type":"listen","title":"Слушаем: Китай и китайский","items":[{"say":"中国","options":["Zhōngguó","Zhōngguò","Zhóngguó"],"correct":0},{"say":"北京","options":["Běijīng","Béijīng","Bèijīng"],"correct":0},{"say":"人","options":["rén","rěn","rèn"],"correct":0},{"say":"汉语","options":["Hànyǔ","Hànyù","Hānyǔ"],"correct":0},{"say":"我是中国人","options":["wǒ shì Zhōngguó rén","wǒ shì Běijīng rén"],"correct":0}]}'),
  ('hsk1-03-1', 8, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","是","中国人"],"hint":"«Я китаец.»"},{"answer":["他","是","北京人"],"hint":"«Он из Пекина.»"},{"answer":["你","是","中国人","吗"],"hint":"«Ты китаец?»"}]}'),
  ('hsk1-03-1', 9, 'write', '{"title":"Пропись: человек, середина, страна","items":[{"hanzi":"人","pinyin":"rén","m":"человек","hint":"Откидная 丿, потом捺 ㇏"},{"hanzi":"中","pinyin":"zhōng","m":"середина","hint":"Рамка, потом вертикаль сквозь неё"},{"hanzi":"国","pinyin":"guó","m":"страна","hint":"Сначала рамка, внутри 玉, закрываем снизу"}]}'),
  ('hsk1-03-1', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 中国?","options":["Китай","Пекин","человек","учитель"],"correct":0},{"q":"Из чего состоит 中国?","options":["середина + страна","север + столица","человек + язык"],"correct":0},{"q":"Как сказать «пекинец»?","options":["北京人","中国人","汉语人"],"correct":0},{"q":"人 нарисован как идущий человек.","tf":true},{"q":"Что значит 汉语?","options":["китайский язык","китайская страна","китайская еда"],"correct":0}]}'),
  ('hsk1-03-2', 1, 'fact', '{"emoji":"🛠️","title":"Глагол «уметь» — маленький помощник","text":"В китайском 会 стоит перед другим глаголом и означает «умею, могу (потому что научился)»: 会说汉语 — «умею говорить по-китайски». Ответ на вопрос тоже короткий: 会 («умею») или 不会 («не умею»). Повторяйте глагол из вопроса вместо «да/нет»."}'),
  ('hsk1-03-2', 2, 'words', '{"title":"Два слова-помощника","items":[{"hanzi":"说","pinyin":"shuō","m":"говорить","emoji":"🗣️","ex":{"zh":"我说汉语。","py":"Wǒ shuō Hànyǔ.","m":"Я говорю по-китайски."}},{"hanzi":"会","pinyin":"huì","m":"уметь, мочь","emoji":"💪","ex":{"zh":"我会说汉语。","py":"Wǒ huì shuō Hànyǔ.","m":"Я умею говорить по-китайски."}}]}'),
  ('hsk1-03-2', 3, 'theory', '{"title":"说 + язык","blocks":[{"t":"table","head":["Фраза","Пиньинь","Перевод"],"rows":[["我说汉语。","Wǒ shuō Hànyǔ.","Я говорю по-китайски."],["他说汉语。","Tā shuō Hànyǔ.","Он говорит по-китайски."],["我不说汉语。","Wǒ bù shuō Hànyǔ.","Я не говорю по-китайски."]]},{"t":"tip","text":"说 в первом тоне, поэтому 不 остаётся bù: 不说."}]}'),
  ('hsk1-03-2', 4, 'theory', '{"title":"会 + глагол","blocks":[{"t":"table","head":["Вопрос","Ответ «да»","Ответ «нет»"],"rows":[["你会说汉语吗？","会。","不会。"],["她会说汉语吗？","她会。","她不会。"]]},{"t":"p","text":"会 уже включает «умею», поэтому добавляйте только действие: 会说汉语. 不 перед 会 (4 тон) читается bú: 不会 bú huì."},{"t":"ex","zh":"你会说汉语吗？","py":"Nǐ huì shuō Hànyǔ ma?","m":"Ты умеешь говорить по-китайски?","say":"你会说汉语吗"}]}'),
  ('hsk1-03-2', 5, 'quiz', '{"title":"Мини-тест: 会","qs":[{"q":"Как ответить «Нет, не умею» на вопрос 你会说汉语吗？","options":["不会。","不说。","不是。"],"correct":0},{"q":"Как читается 不 в 不会?","options":["bú","bù","bǔ"],"correct":0},{"q":"Для ответа «умею» можно просто сказать 会.","tf":true}]}'),
  ('hsk1-03-2', 6, 'game', '{"type":"build","title":"Соберите предложение","items":[{"answer":["我","会","说","汉语"],"hint":"«Я умею говорить по-китайски.»"},{"answer":["你","会","说","汉语","吗"],"hint":"«Ты умеешь говорить по-китайски?»"},{"answer":["她","不","会","说","汉语"],"hint":"«Она не умеет говорить по-китайски.»"}]}'),
  ('hsk1-03-2', 7, 'game', '{"type":"listen","title":"Слушаем: 不 + 说 / 会","items":[{"say":"不说","options":["bù shuō","bú shuō"],"correct":0,"explain":"说 в 1 тоне, поэтому 不 остаётся bù."},{"say":"不会","options":["bú huì","bù huì"],"correct":0,"explain":"会 в 4 тоне, поэтому 不 → bú."},{"say":"你会说汉语吗","options":["nǐ huì shuō Hànyǔ ma","nǐ shì shuō Hànyǔ ma"],"correct":0},{"say":"她会说汉语","options":["tā huì shuō Hànyǔ","tā bú huì shuō Hànyǔ"],"correct":0}]}'),
  ('hsk1-03-2', 8, 'game', '{"type":"match","title":"Что значит","pairs":[["说","говорить"],["会","уметь"],["不会","не уметь"],["说汉语","говорить по-китайски"],["会说汉语","уметь говорить по-китайски"]]}'),
  ('hsk1-03-2', 9, 'game', '{"type":"bughunt","title":"Китайский детектив: ошибки в 说 и 会","cases":[{"buggyText":"你会汉语说吗？","context":"Спросить «Ты умеешь говорить по-китайски?»","options":["你会说汉语吗？","你说会汉语吗？","你吗会说汉语？"],"correct":0},{"buggyText":"我会不说汉语。","context":"Сказать «Я не умею говорить по-китайски»","options":["我不会说汉语。","我说不会汉语。","我不说会汉语。"],"correct":0},{"buggyText":"我是说汉语。","context":"Сказать «Я говорю по-китайски»","options":["我说汉语。","我说是汉语。","是我说汉语。"],"correct":0,"explain":"Глагол 是 здесь не нужен."}]}'),
  ('hsk1-03-2', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Какое слово значит «уметь»?","options":["会","说","是"],"correct":0},{"q":"Как сказать «Я не говорю по-китайски»?","options":["我不说汉语。","我是说汉语。","我说不汉语。"],"correct":0},{"q":"会 ставится перед глаголом.","tf":true},{"q":"Как спросить «Она умеет говорить по-китайски?»","options":["她会说汉语吗？","她说会汉语吗？","她会汉语说吗？"],"correct":0},{"q":"Как читается 不 в 不说?","options":["bù","bú","bǔ"],"correct":0}]}'),
  ('hsk1-03-3', 1, 'fact', '{"emoji":"🏫","title":"Ребёнок под крышей","text":"Знак 学 «учиться» нарисован как ребёнок 子 под крышей: старые 學 показывали руки, которые учат малыша. В 校 «школа» слева 木 «дерево», справа 交 «пересекаться»: школы стояли в роще. 同学 — «те, кто учится вместе», то есть одноклассник или соученик. Так обращаются к своим ровесникам."}'),
  ('hsk1-03-3', 2, 'words', '{"title":"Четыре слова про учёбу","items":[{"hanzi":"学习","pinyin":"xuéxí","m":"учиться, изучать","emoji":"📚","ex":{"zh":"我学习汉语。","py":"Wǒ xuéxí Hànyǔ.","m":"Я учу китайский."}},{"hanzi":"学校","pinyin":"xuéxiào","m":"школа, университет","emoji":"🏫","ex":{"zh":"我的学校","py":"wǒ de xuéxiào","m":"моя школа"}},{"hanzi":"学生","pinyin":"xuésheng","m":"ученик, студент","emoji":"🎓","ex":{"zh":"我是学生。","py":"Wǒ shì xuésheng.","m":"Я студент."}},{"hanzi":"同学","pinyin":"tóngxué","m":"одноклассник, соученик","emoji":"🧑‍🤝‍🧑","ex":{"zh":"同学，你好！","py":"Tóngxué, nǐ hǎo!","m":"Привет, одноклассник!"}}]}'),
  ('hsk1-03-3', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"📚","options":["学习","学校","同学"],"correct":0},{"emoji":"🏫","options":["学校","学生","汉语"],"correct":0},{"emoji":"🎓","options":["学生","老师","同学"],"correct":0},{"emoji":"🧑‍🤝‍🧑","options":["同学","学习","人"],"correct":0}]}'),
  ('hsk1-03-3', 4, 'game', '{"type":"listen","title":"Слушаем: все четыре слова","items":[{"say":"学习","options":["xuéxí","xuéxì","xuēxí"],"correct":0,"explain":"Оба слога во 2 тоне."},{"say":"学校","options":["xuéxiào","xuēxiào","xuéxiāo"],"correct":0},{"say":"学生","options":["xuésheng","xuéshēng","xuěsheng"],"correct":0,"explain":"Второй слог безударный."},{"say":"同学","options":["tóngxué","tòngxué","tǒngxué"],"correct":0},{"say":"我学习汉语","options":["wǒ xuéxí Hànyǔ","wǒ xuéxí Zhōngguó"],"correct":0}]}'),
  ('hsk1-03-3', 5, 'game', '{"type":"tone_visualizer","initialTone":2,"title":"Тренажёр голоса: повторите «xué» (2 тон)"}'),
  ('hsk1-03-3', 6, 'theory', '{"title":"Кто есть кто в школе","blocks":[{"t":"table","head":["Слово","Смысл","Когда говорят"],"rows":[["老师","учитель","к преподавателю, Вы"],["学生","ученик, студент","о себе и других"],["同学","соученик","к ровесникам, друзьям по классу"],["学校","школа","место, где учатся"]]},{"t":"p","text":"Схема «学习 + что»: 学习汉语 — «изучать китайский». Подлежащее: 我学习汉语, 她学习汉语。"},{"t":"tip","text":"同学们好！ — так учитель здоровается с классом. Знак 们 вы уже знаете."}]}'),
  ('hsk1-03-3', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["学习","учиться, изучать"],["学校","школа"],["学生","ученик, студент"],["同学","одноклассник"],["学习汉语","изучать китайский"]]}'),
  ('hsk1-03-3', 8, 'game', '{"type":"chatsim","title":"WeChat: в школьном чате","messages":[{"speaker":"Ли Мин","text":"你好！你是学生吗？","pinyin":"Nǐ hǎo! Nǐ shì xuésheng ma?","translation":"Привет! Ты студент?","options":["是，我是学生。","我是老师。","我叫学生。"],"correct":0},{"speaker":"Ли Мин","text":"你学习什么？","pinyin":"Nǐ xuéxí shénme?","translation":"Что ты изучаешь?","options":["我学习汉语。","我是汉语。","我叫汉语。"],"correct":0},{"speaker":"Ли Мин","text":"我们是同学！","pinyin":"Wǒmen shì tóngxué!","translation":"Мы одноклассники!","options":["你好，同学！","再见，老师！","不客气。"],"correct":0}]}'),
  ('hsk1-03-3', 9, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","学习","汉语"],"hint":"«Я изучаю китайский.»"},{"answer":["他","是","我","同学"],"hint":"«Он мой одноклассник.»"},{"answer":["她","是","学生"],"hint":"«Она студентка.»"}]}'),
  ('hsk1-03-3', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 学生?","options":["ученик, студент","школа","учитель","учиться"],"correct":0},{"q":"Какое слово значит «одноклассник»?","options":["同学","学校","学习"],"correct":0},{"q":"Как читается 学生?","options":["xuésheng","xuéshēng","xuěsheng"],"correct":0},{"q":"学校 — это «школа».","tf":true},{"q":"Как сказать «Я изучаю китайский»?","options":["我学习汉语。","我是学习汉语。","汉语学习我。"],"correct":0}]}'),
  ('hsk1-03-4', 1, 'fact', '{"emoji":"🎒","title":"Разговор у школьных ворот","text":"Тут вы читаете диалог, в котором встречаются слова трёх глав: приветствия, знакомство и школа. Подсказок на русском внутри реплик нет — только на вкладке перевода."}'),
  ('hsk1-03-4', 2, 'text', '{"title":"Разговор у школьных ворот","lines":[{"zh":"安娜：你好！你是中国人吗？","py":"Ānnà: Nǐ hǎo! Nǐ shì Zhōngguó rén ma?","m":"Анна: Привет! Ты китаец?"},{"zh":"李明：是。我是北京人。你叫什么名字？","py":"Lǐ Míng: Shì. Wǒ shì Běijīng rén. Nǐ jiào shénme míngzi?","m":"Ли Мин: Да. Я из Пекина. Как тебя зовут?"},{"zh":"安娜：我叫安娜。我是学生。我学习汉语。","py":"Ānnà: Wǒ jiào Ānnà. Wǒ shì xuésheng. Wǒ xuéxí Hànyǔ.","m":"Анна: Меня зовут Анна. Я студентка. Я изучаю китайский."},{"zh":"李明：你会说汉语吗？","py":"Lǐ Míng: Nǐ huì shuō Hànyǔ ma?","m":"Ли Мин: Ты умеешь говорить по-китайски?"},{"zh":"安娜：会，我会说汉语。","py":"Ānnà: Huì, wǒ huì shuō Hànyǔ.","m":"Анна: Умею, я умею говорить по-китайски."},{"zh":"李明：很好！我们是同学。","py":"Lǐ Míng: Hěn hǎo! Wǒmen shì tóngxué.","m":"Ли Мин: Отлично! Мы одноклассники."},{"zh":"安娜：同学，再见！","py":"Ānnà: Tóngxué, zàijiàn!","m":"Анна: До свидания, одноклассник!"}],"qs":[{"q":"Откуда Ли Мин?","options":["из Пекина","из Шанхая","не сказано"],"correct":0},{"q":"Анна студентка.","tf":true},{"q":"Что изучает Анна?","options":["汉语","学校","北京"],"correct":0},{"q":"Анна не умеет говорить по-китайски.","tf":false,"explain":"Она отвечает 会."},{"q":"Вставьте слово: 我们是___。","options":["同学","老师","北京"],"correct":0},{"q":"Как Ли Мин узнаёт, умеет ли Анна говорить?","options":["你会说汉语吗？","你是中国人吗？","你叫什么？"],"correct":0},{"q":"Ли Мин — не китаец.","tf":false,"explain":"Он говорит: 我是北京人."}]}'),
  ('hsk1-03-4', 3, 'game', '{"type":"match","title":"Реплика и перевод","pairs":[["你是中国人吗？","Ты китаец?"],["我是北京人。","Я из Пекина."],["我学习汉语。","Я изучаю китайский."],["我们是同学。","Мы одноклассники."],["会。","Умею."]]}'),
  ('hsk1-03-4', 4, 'game', '{"type":"listen","title":"Слышим реплики из диалога","items":[{"say":"你是中国人吗","options":["nǐ shì Zhōngguó rén ma","nǐ shì Běijīng rén ma"],"correct":0},{"say":"我是北京人","options":["wǒ shì Běijīng rén","wǒ shì Zhōngguó rén"],"correct":0},{"say":"你会说汉语吗","options":["nǐ huì shuō Hànyǔ ma","nǐ huì xuéxí Hànyǔ ma"],"correct":0},{"say":"我们是同学","options":["wǒmen shì tóngxué","wǒmen shì xuésheng"],"correct":0}]}'),
  ('hsk1-03-4', 5, 'game', '{"type":"bughunt","title":"Китайский детектив: ошибки в диалоге","cases":[{"buggyText":"你是中国吗？","context":"Спросить: «Ты китаец?»","options":["你是中国人吗？","你中国是人吗？","你是人中国吗？"],"correct":0},{"buggyText":"我是学习汉语。","context":"Сказать: «Я изучаю китайский»","options":["我学习汉语。","我学习是汉语。","是我学习汉语。"],"correct":0},{"buggyText":"我会不说汉语。","context":"Сказать: «Я не умею говорить по-китайски»","options":["我不会说汉语。","我说不会汉语。","我不说会汉语。"],"correct":0}]}'),
  ('hsk1-03-4', 6, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как переводится 同学，再见！","options":["Одноклассник, до свидания!","Учитель, спасибо!","Одноклассник, привет!"],"correct":0},{"q":"Какой вопрос задаёт Ли Мин про язык?","options":["你会说汉语吗？","你叫什么名字？","你是学生吗？"],"correct":0},{"q":"Анна изучает китайский язык.","tf":true},{"q":"Какое слово значит «Пекин»?","options":["北京","中国","汉语"],"correct":0}]}'),
  ('hsk1-03-5', 1, 'fact', '{"emoji":"💌","title":"Откройте свою открытку из Китая","text":"Здесь вы будете собирать знаки из частей и писать открытки друзьям. Каждая реплика состоит из слов глав 1–3."}'),
