  ('hsk1-03-5', 4, 'game', '{"type":"build","title":"Мастерская открыток","items":[{"target":"(Открытка)","answer":["我","是","学生"],"hint":"«Я студент.»"},{"target":"(Открытка)","answer":["我","学习","汉语"],"hint":"«Я изучаю китайский.»"},{"target":"(Открытка)","answer":["你","好","，","北京"],"hint":"«Привет, Пекин!»"},{"target":"(Открытка)","answer":["我","很","高兴"],"hint":"«Я очень рад.»"}]}'),
  ('hsk1-03-5', 5, 'theory', '{"title":"Шаблон открытки","blocks":[{"t":"table","head":["Часть","Пример"],"rows":[["Приветствие","你好，同学！"],["О себе","我是学生。我学习汉语。"],["Эмоция","我很高兴！"],["Прощание","再见！"]]},{"t":"tip","text":"Составьте открытку из четырёх фраз и прочитайте её вслух."}]}'),
  ('hsk1-03-5', 6, 'game', '{"type":"chatsim","title":"WeChat: расскажите о себе","messages":[{"speaker":"Ли Мин","text":"你好！你是学生吗？","pinyin":"Nǐ hǎo! Nǐ shì xuésheng ma?","translation":"Привет! Ты студент?","options":["是，我是学生。","我是老师。","我叫学生。"],"correct":0},{"speaker":"Ли Мин","text":"你会说汉语吗？","pinyin":"Nǐ huì shuō Hànyǔ ma?","translation":"Ты умеешь говорить по-китайски?","options":["会。","不是。","你好。"],"correct":0},{"speaker":"Ли Мин","text":"你是中国人吗？","pinyin":"Nǐ shì Zhōngguó rén ma?","translation":"Ты китаец?","options":["不是，我不是中国人。","我是学校。","我说汉语。"],"correct":0,"explain":"Отрицание: 不是."}]}'),
  ('hsk1-03-5', 7, 'game', '{"type":"match","title":"Какой знак получится","pairs":[["氵 + 又","汉"],["木 + 交","校"],["囗 + 玉","国"],["亻 + 门","们"]]}'),
