  ('hsk1-03-5', 9, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что нужно написать на открытке: «Я студент»?","options":["我是学生。","我学校。","我是中国人学生。"],"correct":0},{"q":"Какой ключ слева в 汉?","options":["氵","亻","女"],"correct":0},{"q":"Какая фраза подходит для подписи под открыткой?","options":["再见！","对不起！","你叫什么？"],"correct":0},{"q":"Шаблон открытки состоит из четырёх частей.","tf":true}]}'),
  ('hsk1-03-6', 1, 'fact', '{"emoji":"🏁","title":"Экзамен главы 3","text":"Проверяем слова про страну, учёбу, глаголы 说 и 会 и схему «страна + 人»."}'),
  ('hsk1-03-6', 2, 'game', '{"type":"listen","title":"Аудирование","items":[{"say":"我是中国人","options":["wǒ shì Zhōngguó rén","wǒ shì Běijīng rén","wǒ shì xuésheng"],"correct":0},{"say":"他是北京人","options":["tā shì Běijīng rén","tā shì Zhōngguó rén"],"correct":0},{"say":"你会说汉语吗","options":["nǐ huì shuō Hànyǔ ma","nǐ xuéxí Hànyǔ ma"],"correct":0},{"say":"她不会说汉语","options":["tā bú huì shuō Hànyǔ","tā bù huì shuō Hànyǔ"],"correct":0},{"say":"我学习汉语","options":["wǒ xuéxí Hànyǔ","wǒ shuō Hànyǔ"],"correct":0},{"say":"我们是同学","options":["wǒmen shì tóngxué","wǒmen shì lǎoshī"],"correct":0}]}'),
  ('hsk1-03-6', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🇨🇳","options":["中国","北京","学校"],"correct":0},{"emoji":"🏫","options":["学校","汉语","同学"],"correct":0},{"emoji":"🎓","options":["学生","老师","学习"],"correct":0},{"emoji":"📚","options":["学习","说","会"],"correct":0}]}'),
  ('hsk1-03-6', 4, 'game', '{"type":"match","title":"Слова главы","pairs":[["中国","Китай"],["北京","Пекин"],["人","человек"],["汉语","китайский язык"],["说","говорить"],["会","уметь"],["学习","учиться"],["学校","школа"],["学生","студент"],["同学","одноклассник"]]}'),
  ('hsk1-03-6', 5, 'quiz', '{"title":"Экзаменационные вопросы","qs":[{"q":"Как сказать «Я китаец»?","options":["我是中国人。","我中国是人。","中国我是。"],"correct":0},{"q":"Как спросить «Ты умеешь говорить по-китайски?»","options":["你会说汉语吗？","你说会汉语吗？","汉语你会说吗？"],"correct":0},{"q":"Как читается 不 в 不会?","options":["bú","bù","bǔ"],"correct":0},{"q":"说 — это «учиться».","tf":false},{"q":"Что значит 学校?","options":["школа","ученик","учитель"],"correct":0},{"q":"Как сказать «Он мой одноклассник»?","options":["他是我同学。","他学校我。","他是学习。"],"correct":0},{"q":"北京 значит «северная столица».","tf":true},{"q":"Как читается 学生?","options":["xuésheng","xuéshēng","xuěsheng"],"correct":0},{"q":"Как ответить на 你会说汉语吗？ «Нет»?","options":["不会。","不是。","不说是。"],"correct":0},{"q":"Какой иероглиф означает «человек»?","options":["人","中","国"],"correct":0}]}'),
  ('hsk1-03-6', 6, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","是","北京人"],"hint":"«Я из Пекина.»"},{"answer":["她","会","说","汉语"],"hint":"«Она умеет говорить по-китайски.»"},{"answer":["我","学习","汉语"],"hint":"«Я изучаю китайский.»"},{"answer":["我们","是","同学"],"hint":"«Мы одноклассники.»"}]}'),
  ('hsk1-03-6', 7, 'game', '{"type":"bughunt","title":"Найдите ошибку","cases":[{"buggyText":"你是中国吗？","context":"Спросить «Ты китаец?»","options":["你是中国人吗？","你中国是人吗？","你是人中国吗？"],"correct":0},{"buggyText":"我会不说汉语。","context":"«Я не умею говорить по-китайски»","options":["我不会说汉语。","我说不会汉语。","我不说会汉语。"],"correct":0},{"buggyText":"我是学习汉语。","context":"«Я изучаю китайский»","options":["我学习汉语。","我是学习汉语的。","我学习是汉语。"],"correct":0}]}'),
  ('hsk1-03-6', 8, 'game', '{"type":"chatsim","title":"Мини-чат","messages":[{"speaker":"Ли Мин","text":"你是中国人吗？","pinyin":"Nǐ shì Zhōngguó rén ma?","translation":"Ты китаец?","options":["不是，我不是中国人。","我是学校。","我说汉语人。"],"correct":0},{"speaker":"Ли Мин","text":"你学习什么？","pinyin":"Nǐ xuéxí shénme?","translation":"Что ты изучаешь?","options":["我学习汉语。","我是汉语。","我叫学习。"],"correct":0}]}'),
  ('hsk1-03-6', 9, 'write', '{"title":"Пропись по памяти","items":[{"hanzi":"人","pinyin":"rén","m":"человек","hint":"Две черты: 丿 и ㇏"},{"hanzi":"国","pinyin":"guó","m":"страна","hint":"囗 + 玉"},{"hanzi":"学","pinyin":"xué","m":"учиться","hint":"⺍ + 冖 + 子"}]}'),
  ('hsk1-03-6', 10, 'recall', '{"words":[{"hanzi":"中国","pinyin":"Zhōngguó","m":"Китай"},{"hanzi":"北京","pinyin":"Běijīng","m":"Пекин"},{"hanzi":"人","pinyin":"rén","m":"человек"},{"hanzi":"汉语","pinyin":"Hànyǔ","m":"китайский язык"},{"hanzi":"说","pinyin":"shuō","m":"говорить"},{"hanzi":"会","pinyin":"huì","m":"уметь"},{"hanzi":"学习","pinyin":"xuéxí","m":"учиться"},{"hanzi":"学校","pinyin":"xuéxiào","m":"школа"},{"hanzi":"学生","pinyin":"xuésheng","m":"студент"},{"hanzi":"同学","pinyin":"tóngxué","m":"одноклассник"},{"hanzi":"叫","pinyin":"jiào","m":"звать"},{"hanzi":"认识","pinyin":"rènshi","m":"знать"}],"tf":[{"zh":"我会说不汉语。","py":"wǒ huì shuō bù Hànyǔ.","m":"Я не умею говорить по-китайски.","ok":false,"explain":"Правильно: 我不会说汉语."},{"zh":"他是北京人。","py":"tā shì Běijīng rén.","m":"Он из Пекина.","ok":true}],"sentences":[{"zh":"我是中国人。","tokens":["我","是","中国人"],"m":"Я китаец."},{"zh":"我学习汉语。","tokens":["我","学习","汉语"],"m":"Я изучаю китайский."},{"zh":"我们是同学。","tokens":["我们","是","同学"],"m":"Мы одноклассники."}]}'),
  ('hsk1-04-1', 1, 'fact', '{"emoji":"🔢","title":"Первые три числа — это просто чёрточки","text":"一, 二, 三: одна, две и три горизонтальные черты. Дальше всё сложнее, зато вы уже знаете порядок черт с Уровня 0. А 四 «четыре» китайцы побаиваются: звучит почти как 死 sǐ «смерть». В некоторых зданиях нет четвёртого этажа или номера 14."}'),
  ('hsk1-04-1', 2, 'words', '{"title":"Первые четыре числа","items":[{"hanzi":"一","pinyin":"yī","m":"один","emoji":"1️⃣","ex":{"zh":"一，二，三！","py":"Yī, èr, sān!","m":"Раз, два, три!"}},{"hanzi":"二","pinyin":"èr","m":"два","emoji":"2️⃣","ex":{"zh":"二，三，四。","py":"Èr, sān, sì.","m":"Два, три, четыре."}},{"hanzi":"三","pinyin":"sān","m":"три","emoji":"3️⃣","ex":{"zh":"三，二，一！","py":"Sān, èr, yī!","m":"Три, два, раз!"}},{"hanzi":"四","pinyin":"sì","m":"четыре","emoji":"4️⃣","ex":{"zh":"一，二，三，四。","py":"Yī, èr, sān, sì.","m":"Раз, два, три, четыре."}}]}'),
  ('hsk1-04-1', 3, 'game', '{"type":"emoji","big":true,"title":"Цифра → иероглиф","items":[{"emoji":"1️⃣","options":["一","二","三"],"correct":0},{"emoji":"2️⃣","options":["三","二","四"],"correct":1},{"emoji":"3️⃣","options":["三","四","一"],"correct":0},{"emoji":"4️⃣","options":["二","三","四"],"correct":2}]}'),
  ('hsk1-04-1', 4, 'theory', '{"title":"Числа 1–4 и их особенности","blocks":[{"t":"table","head":["Число","Иероглиф","Фишка"],"rows":[["1","一","одна горизонтальная черта"],["2","二","две черты; верхняя короче нижней"],["3","三","три черты"],["4","四","рамка 囗 и внутри 儿; созвучно «смерти»"]]},{"t":"tip","text":"Именно поэтому в китайских гостиницах и больницах часто нет 4-го и 14-го этажей, а нумерация перескакивает."}]}'),
  ('hsk1-04-1', 5, 'quiz', '{"title":"Мини-тест: числа 1–4","qs":[{"q":"Какое число состоит из двух горизонтальных черт?","options":["二","三","四"],"correct":0},{"q":"四 китайцы считают счастливым числом.","tf":false,"explain":"Оно созвучно 死 «смерть»."},{"q":"Как читается 三?","options":["sān","sǎn","sàn"],"correct":0}]}'),
  ('hsk1-04-1', 6, 'game', '{"type":"match","title":"Иероглиф и число","pairs":[["一","один"],["二","два"],["三","три"],["四","четыре"],["一二三四","раз, два, три, четыре"]]}'),
  ('hsk1-04-1', 7, 'game', '{"type":"listen","title":"Слушаем: числа","items":[{"say":"一","options":["yī","yí","yǐ"],"correct":0},{"say":"二","options":["èr","ér","ěr"],"correct":0},{"say":"三","options":["sān","sǎn","sàn"],"correct":0},{"say":"四","options":["sì","sī","sǐ"],"correct":0,"explain":"Тон четвёртый, падающий."},{"say":"一二三四","options":["yī èr sān sì","yī èr sān sǐ"],"correct":0}]}'),
  ('hsk1-04-1', 8, 'game', '{"type":"build","title":"Соберите счёт","items":[{"answer":["一","二","三"],"hint":"Посчитайте: «раз, два, три»"},{"answer":["四","三","二","一"],"hint":"Обратный отсчёт: 4, 3, 2, 1"},{"answer":["二","三","四"],"hint":"Цифры 2, 3, 4"}]}'),
  ('hsk1-04-1', 9, 'write', '{"title":"Пропись: числа 1–4","items":[{"hanzi":"一","pinyin":"yī","m":"один","hint":"Одна горизонтальная черта слева направо"},{"hanzi":"二","pinyin":"èr","m":"два","hint":"Сначала короткая верхняя, потом длинная нижняя"},{"hanzi":"三","pinyin":"sān","m":"три","hint":"Три черты сверху вниз"},{"hanzi":"四","pinyin":"sì","m":"четыре","hint":"Рамка 囗, внутри 儿"}]}'),
  ('hsk1-04-1', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «три»?","options":["三","二","四"],"correct":0},{"q":"Как читается 二?","options":["èr","ér","ěr"],"correct":0},{"q":"В 一 всего одна черта.","tf":true},{"q":"Почему китайцы избегают числа 4?","options":["созвучно слову «смерть»","оно слишком большое","оно звучит как «один»"],"correct":0},{"q":"Какую последовательность вы слышите: 一二三四?","options":["yī èr sān sì","yī èr sì sān"],"correct":0}]}'),
  ('hsk1-04-2', 1, 'fact', '{"emoji":"🧮","title":"Китайские числа логичны, как конструктор","text":"Двадцать — это «два десять» (二十), двадцать один — «два десять один» (二十一). Запоминать особые слова вроде «одиннадцать» или «девяносто» не нужно. Для счёта людей и предметов нужно счётное слово 个: «один человек» — это «один штука человек»."}'),
  ('hsk1-04-2', 2, 'words', '{"title":"Четыре слова для счёта","items":[{"hanzi":"十","pinyin":"shí","m":"десять","emoji":"🔟","ex":{"zh":"十，二十，三十。","py":"Shí, èrshí, sānshí.","m":"Десять, двадцать, тридцать."}},{"hanzi":"个","pinyin":"gè","m":"штука (счётное слово)","emoji":"🧩","ex":{"zh":"一个人","py":"yí gè rén","m":"один человек"}},{"hanzi":"几","pinyin":"jǐ","m":"сколько (до 10)","emoji":"❔","ex":{"zh":"你几岁？","py":"Nǐ jǐ suì?","m":"Сколько тебе лет?"}},{"hanzi":"岁","pinyin":"suì","m":"год (о возрасте)","emoji":"🎂","ex":{"zh":"我二十岁。","py":"Wǒ èrshí suì.","m":"Мне двадцать лет."}}]}'),
  ('hsk1-04-2', 3, 'theory', '{"title":"Числа от 11 до 99","blocks":[{"t":"table","head":["Число","Как строится","Китайский"],"rows":[["11","десять + один","十一 shíyī"],["14","десять + четыре","十四 shísì"],["20","два + десять","二十 èrshí"],["24","два + десять + четыре","二十四 èrshísì"],["43","четыре + десять + три","四十三 sìshísān"]]},{"t":"p","text":"Читайте как схему: десятки + 十 + единицы. Никаких исключений."},{"t":"tip","text":"Слева направо: сначала цифра десятков, потом 十, потом единицы."}]}'),
  ('hsk1-04-2', 4, 'game', '{"type":"build","title":"Соберите число","items":[{"answer":["十","二"],"hint":"12"},{"answer":["二","十"],"hint":"20"},{"answer":["二","十","四"],"hint":"24"},{"answer":["四","十","三"],"hint":"43"}]}'),
  ('hsk1-04-2', 5, 'quiz', '{"title":"Мини-тест: десятки","qs":[{"q":"Как сказать «двадцать»?","options":["二十","十二","二个十"],"correct":0},{"q":"Как будет 14?","options":["十四","四十","一十四"],"correct":0},{"q":"21 по-китайски — 二十一.","tf":true}]}'),
  ('hsk1-04-2', 6, 'theory', '{"title":"Счётное слово 个","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["一个人","один человек"],["三个人","три человека"],["几个人？","сколько человек?"]]},{"t":"p","text":"Между числом и словом о людях ставится 个. По-русски мы этого не делаем, а по-китайски нельзя пропустить."},{"t":"ex","zh":"你们几个人？","py":"Nǐmen jǐ gè rén?","m":"Сколько вас человек?","say":"你们几个人"}]}'),
  ('hsk1-04-2', 7, 'theory', '{"title":"Скрытая фишка: число 一 меняет тон","blocks":[{"t":"table","head":["После 一 идёт","Как читаем 一","Пример"],"rows":[["1, 2, 3 тон","yì (4 тон)","一天 yì tiān"],["4 тон","yí (2 тон)","一个 yí gè"],["числа, счёт, конец слова","yī (1 тон)","一，二，三"]]},{"t":"tip","text":"Пишется 一 всегда одинаково, меняется только звук."}]}'),
  ('hsk1-04-2', 8, 'game', '{"type":"listen","title":"Слушаем: числа и возраст","items":[{"say":"一个人","options":["yí gè rén","yī gè rén","yì gè rén"],"correct":0,"explain":"个 — 4 тон, поэтому 一 → yí."},{"say":"二十","options":["èrshí","èrshì","érshí"],"correct":0},{"say":"十四","options":["shísì","shíshí","sìshí"],"correct":0},{"say":"你几岁","options":["nǐ jǐ suì","nǐ jí suì"],"correct":0},{"say":"我二十岁","options":["wǒ èrshí suì","wǒ èrshí shì"],"correct":0}]}'),
  ('hsk1-04-2', 9, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["十","десять"],["个","счётное слово"],["几","сколько (до 10)"],["岁","год жизни"],["二十四","двадцать четыре"]]}'),
  ('hsk1-04-2', 10, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","二","十","岁"],"hint":"«Мне двадцать лет.»"},{"answer":["你","几","岁"],"hint":"«Сколько тебе лет?»"},{"answer":["三","个","人"],"hint":"«Три человека.»"},{"answer":["你们","几","个","人"],"hint":"«Сколько вас человек?»"}]}'),
  ('hsk1-04-2', 11, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как читается 一个?","options":["yí gè","yī gè","yì gè"],"correct":0},{"q":"Что значит 几?","options":["сколько (до 10)","десять","год"],"correct":0},{"q":"Как сказать «Мне десять лет»?","options":["我十岁。","我十个。","我岁十。"],"correct":0},{"q":"Между числом и словом «человек» нужно счётное слово 个.","tf":true},{"q":"Как будет 31?","options":["三十一","一十三","三一十"],"correct":0}]}'),
  ('hsk1-04-3', 1, 'fact', '{"emoji":"🍀","title":"Числа-«переводчики»","text":"Китайцы любят числа за их созвучие. 八 bā почти как 发 fā «богатеть», поэтому номера с восьмёрками стоят очень дорого. 六 liù близко к 顺 shùn «гладко», а 九 jiǔ к 久 jiǔ «долго, навсегда». В сетевом сленге 520 (wǔ èr líng) читается как «я люблю тебя» — 我爱你 wǒ ài nǐ."}'),
  ('hsk1-04-3', 2, 'words', '{"title":"Числа 5–9","items":[{"hanzi":"五","pinyin":"wǔ","m":"пять","emoji":"5️⃣","ex":{"zh":"五，六，七。","py":"Wǔ, liù, qī.","m":"Пять, шесть, семь."}},{"hanzi":"六","pinyin":"liù","m":"шесть","emoji":"6️⃣","ex":{"zh":"六个人","py":"liù gè rén","m":"шесть человек"}},{"hanzi":"七","pinyin":"qī","m":"семь","emoji":"7️⃣","ex":{"zh":"七，八，九。","py":"Qī, bā, jiǔ.","m":"Семь, восемь, девять."}},{"hanzi":"八","pinyin":"bā","m":"восемь","emoji":"8️⃣","ex":{"zh":"八个人","py":"bā gè rén","m":"восемь человек"}},{"hanzi":"九","pinyin":"jiǔ","m":"девять","emoji":"9️⃣","ex":{"zh":"九，十。","py":"Jiǔ, shí.","m":"Девять, десять."}}]}'),
  ('hsk1-04-3', 3, 'game', '{"type":"listen","title":"Слушаем: числа 5–9","items":[{"say":"五","options":["wǔ","wú","wù"],"correct":0},{"say":"六","options":["liù","liú","liǔ"],"correct":0},{"say":"七","options":["qī","qí","qǐ"],"correct":0},{"say":"八","options":["bā","bá","bǎ"],"correct":0},{"say":"九","options":["jiǔ","jiú","jiù"],"correct":0},{"say":"五六七八","options":["wǔ liù qī bā","wǔ liù qī bá"],"correct":0}]}'),
  ('hsk1-04-3', 4, 'game', '{"type":"tone_visualizer","initialTone":3,"title":"Тренажёр голоса: повторите «wǔ» (3 тон)"}'),
  ('hsk1-04-3', 5, 'theory', '{"title":"Числа-омофоны","blocks":[{"t":"table","head":["Число","Созвучно","Смысл"],"rows":[["八 bā","发 fā","разбогатеть, процветать"],["六 liù","顺 shùn","гладко, удачно"],["九 jiǔ","久 jiǔ","долго, навсегда"],["四 sì","死 sǐ","смерть (несчастливое)"],["五 wǔ","我 wǒ","«я» (в сленге)"]]},{"t":"tip","text":"Номера телефонов и автомобилей с восьмёрками на аукционах стоят как квартира."}]}'),
  ('hsk1-04-3', 6, 'game', '{"type":"match","title":"Иероглиф и число","pairs":[["五","пять"],["六","шесть"],["七","семь"],["八","восемь"],["九","девять"]]}'),
  ('hsk1-04-3', 7, 'game', '{"type":"emoji","big":true,"title":"Цифра → иероглиф","items":[{"emoji":"5️⃣","options":["五","六","九"],"correct":0},{"emoji":"6️⃣","options":["六","七","八"],"correct":0},{"emoji":"7️⃣","options":["五","七","九"],"correct":1},{"emoji":"8️⃣","options":["八","六","九"],"correct":0},{"emoji":"9️⃣","options":["九","七","八"],"correct":0}]}'),
  ('hsk1-04-3', 8, 'game', '{"type":"chatsim","title":"WeChat: считаем вместе","messages":[{"speaker":"Ли Мин","text":"你几岁？","pinyin":"Nǐ jǐ suì?","translation":"Сколько тебе лет?","options":["我二十岁。","我是二十。","我二十个。"],"correct":0,"explain":"Возраст: число + 岁."},{"speaker":"Ли Мин","text":"你们几个人？","pinyin":"Nǐmen jǐ gè rén?","translation":"Сколько вас человек?","options":["我们八个人。","我们八岁。","我八个。"],"correct":0,"explain":"Люди считаются с 个."},{"speaker":"Ли Мин","text":"你是几号？","pinyin":"Nǐ shì jǐ hào?","translation":"Какой у тебя номер? (号 «номер» — новое слово)","options":["我是九号。","我是九岁。","我是九个人。"],"correct":0}]}'),
  ('hsk1-04-3', 9, 'game', '{"type":"build","title":"Соберите фразу и счёт","items":[{"answer":["我","八","岁"],"hint":"«Мне восемь лет.»"},{"answer":["七","个","人"],"hint":"«Семь человек.»"},{"answer":["十","九","岁"],"hint":"«Девятнадцать лет.»"},{"answer":["五","六","七","八"],"hint":"Посчитайте: 5, 6, 7, 8"}]}'),
  ('hsk1-04-3', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Какое число созвучно «разбогатеть»?","options":["八","四","二"],"correct":0},{"q":"Как читается 九?","options":["jiǔ","jiù","jiú"],"correct":0},{"q":"Как читается 五?","options":["wǔ","wú","wù"],"correct":0},{"q":"六 созвучно «гладко, удачно».","tf":true},{"q":"Как перевести 五六七八?","options":["пять шесть семь восемь","шесть семь восемь девять","четыре пять шесть семь"],"correct":0}]}'),
  ('hsk1-04-4', 1, 'fact', '{"emoji":"🧑‍🏫","title":"Учитель считает класс","text":"Сегодня учитель знакомится с тремя новыми студентами. Прочитайте диалог и проверьте, как работают числа, 个 и 岁 в живой речи."}'),
  ('hsk1-04-4', 2, 'text', '{"title":"Три новых студента","lines":[{"zh":"老师：你们好！你们几个人？","py":"Lǎoshī: Nǐmen hǎo! Nǐmen jǐ gè rén?","m":"Учитель: Здравствуйте! Сколько вас человек?"},{"zh":"李明：老师好！我们三个人。","py":"Lǐ Míng: Lǎoshī hǎo! Wǒmen sān gè rén.","m":"Ли Мин: Здравствуйте! Нас трое."},{"zh":"老师：你们叫什么名字？","py":"Lǎoshī: Nǐmen jiào shénme míngzi?","m":"Учитель: Как вас зовут?"},{"zh":"李明：我叫李明，她叫安娜，他叫大卫。","py":"Lǐ Míng: Wǒ jiào Lǐ Míng, tā jiào Ānnà, tā jiào Dàwèi.","m":"Ли Мин: Меня зовут Ли Мин, её Анна, его Давид."},{"zh":"老师：李明，你几岁？","py":"Lǎoshī: Lǐ Míng, nǐ jǐ suì?","m":"Учитель: Ли Мин, сколько тебе лет?"},{"zh":"李明：我十九岁。安娜二十岁，大卫十八岁。","py":"Lǐ Míng: Wǒ shíjiǔ suì. Ānnà èrshí suì, Dàwèi shíbā suì.","m":"Ли Мин: Мне девятнадцать. Анне двадцать, Давиду восемнадцать."},{"zh":"老师：很好！很高兴认识你们。","py":"Lǎoshī: Hěn hǎo! Hěn gāoxìng rènshi nǐmen.","m":"Учитель: Отлично! Рада познакомиться с вами."}],"qs":[{"q":"Сколько человек в группе?","options":["три","два","четыре"],"correct":0},{"q":"Сколько лет Ли Мину?","options":["19","20","18"],"correct":0},{"q":"Давиду восемнадцать лет.","tf":true},{"q":"Кому двадцать лет?","options":["Анне","Давиду","Ли Мину"],"correct":0},{"q":"В группе четыре человека.","tf":false,"explain":"Ли Мин говорит 三个人."},{"q":"Вставьте слово: 我们三___人。","options":["个","岁","几"],"correct":0},{"q":"Как по-китайски «Давиду восемнадцать лет»?","options":["大卫十八岁","大卫八十岁","大卫十八个"],"correct":0}]}'),
  ('hsk1-04-4', 3, 'game', '{"type":"match","title":"Фраза и смысл","pairs":[["三个人","три человека"],["十九岁","девятнадцать лет"],["二十岁","двадцать лет"],["十八岁","восемнадцать лет"],["你们几个人？","Сколько вас человек?"]]}'),
  ('hsk1-04-4', 4, 'game', '{"type":"listen","title":"Слышим реплики из диалога","items":[{"say":"我们三个人","options":["wǒmen sān gè rén","wǒmen sì gè rén"],"correct":0},{"say":"我十九岁","options":["wǒ shíjiǔ suì","wǒ shíbā suì"],"correct":0},{"say":"大卫十八岁","options":["Dàwèi shíbā suì","Dàwèi shíjiǔ suì"],"correct":0},{"say":"你们几个人","options":["nǐmen jǐ gè rén","nǐmen jǐ suì"],"correct":0}]}'),
  ('hsk1-04-4', 5, 'game', '{"type":"bughunt","title":"Китайский детектив: числа и возраст","cases":[{"buggyText":"我二十个。","context":"Сказать «Мне двадцать лет»","options":["我二十岁。","我二个十岁。","我岁二十。"],"correct":0,"explain":"Возраст — число + 岁."},{"buggyText":"三人。","context":"Сказать «Три человека»","options":["三个人。","三岁人。","三几人。"],"correct":0,"explain":"Не пропускайте 个."},{"buggyText":"我十岁二。","context":"Сказать «Мне двенадцать»","options":["我十二岁。","我二十岁。","我十二个。"],"correct":0}]}'),
  ('hsk1-04-4', 6, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 你几岁？","options":["Сколько тебе лет?","Сколько вас человек?","Как тебя зовут?"],"correct":0},{"q":"Как читается 十八?","options":["shíbā","shíjiǔ","bāshí"],"correct":0},{"q":"Учитель просит назвать имена трёх студентов.","tf":true},{"q":"Как будет 19?","options":["十九","九十","一九"],"correct":0}]}'),
  ('hsk1-04-5', 1, 'fact', '{"emoji":"🎯","title":"Задания на сообразительность","text":"Сегодня вы собираете возраст героев, считаете людей и пишете числа по чертам. Все цифры уже знакомы."}'),
