  ('hsk1-07-6', 7, 'game', '{"type":"bughunt","title":"Найдите ошибку","cases":[{"buggyText":"今天几号吗？","context":"Спросить число","options":["今天几号？","今天几吗号？","几号今天吗？"],"correct":0},{"buggyText":"我买明天。","context":"«Завтра я куплю»","options":["我明天买。","买我明天。","明天买我。"],"correct":0},{"buggyText":"现在点三。","context":"«Сейчас три часа»","options":["现在三点。","三点现在。","现在三号。"],"correct":0}]}'),
