  ('hsk1-08-1', 1, 'fact', '{"emoji":"🌞","title":"Полдень — точка отсчёта","text":"Знак 午 означает «полдень» (в старину — час лошади, 11–13 часов). От него сделаны слова: 上午 «верхняя половина дня» и 下午 «нижняя половина дня». Утро до полудня — 上午, день вокруг — 中午, после полудня — 下午. А 时候 «время, момент» вы встретите в вопросе «когда?»: 什么时候？"}'),
  ('hsk1-08-1', 2, 'words', '{"title":"Части дня","items":[{"hanzi":"上午","pinyin":"shàngwǔ","m":"утро, до полудня","emoji":"🌅","ex":{"zh":"上午九点","py":"shàngwǔ jiǔ diǎn","m":"девять утра"}},{"hanzi":"中午","pinyin":"zhōngwǔ","m":"полдень","emoji":"🌞","ex":{"zh":"中午十二点","py":"zhōngwǔ shí''èr diǎn","m":"двенадцать часов дня"}},{"hanzi":"下午","pinyin":"xiàwǔ","m":"вторая половина дня","emoji":"🌇","ex":{"zh":"下午三点","py":"xiàwǔ sān diǎn","m":"три часа дня"}},{"hanzi":"时候","pinyin":"shíhou","m":"время, момент","emoji":"⏰","ex":{"zh":"什么时候？","py":"Shénme shíhou?","m":"Когда?"}}]}'),
  ('hsk1-08-1', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🌅","options":["上午","中午","下午"],"correct":0},{"emoji":"🌞","options":["中午","上午","时候"],"correct":0},{"emoji":"🌇","options":["下午","中午","上午"],"correct":0},{"emoji":"⏰","options":["时候","上午","现在"],"correct":0}]}'),
  ('hsk1-08-1', 4, 'theory', '{"title":"Время суток и час","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["上午九点","9 утра"],["中午十二点","12 часов дня"],["下午三点","15:00"],["什么时候？","Когда?"]]},{"t":"p","text":"Часть дня ставится перед часом: 下午三点. В вопросе «когда?» используют 什么时候 буквально «в какое время»."},{"t":"tip","text":"Не забудьте: 12 часов — 十二点, а «два часа» — 两点."}]}'),
  ('hsk1-08-1', 5, 'quiz', '{"title":"Мини-тест: время суток","qs":[{"q":"Как сказать «три часа дня»?","options":["下午三点","三点下午","三下午点"],"correct":0},{"q":"上午 — это время до полудня.","tf":true},{"q":"Как спросить «Когда?»","options":["什么时候？","几时候？","时候什么？"],"correct":0}]}'),
  ('hsk1-08-1', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["上午","утро"],["中午","полдень"],["下午","день после полудня"],["时候","время, момент"],["什么时候","когда"]]}'),
  ('hsk1-08-1', 7, 'game', '{"type":"listen","title":"Слушаем: части дня","items":[{"say":"上午","options":["shàngwǔ","shāngwǔ","shàngwú"],"correct":0},{"say":"中午","options":["zhōngwǔ","zhòngwǔ","zhōngwú"],"correct":0},{"say":"下午","options":["xiàwǔ","xiāwǔ","xiàwú"],"correct":0},{"say":"什么时候","options":["shénme shíhou","shénme shíhòu"],"correct":0},{"say":"下午三点","options":["xiàwǔ sān diǎn","shàngwǔ sān diǎn"],"correct":0}]}'),
  ('hsk1-08-1', 8, 'game', '{"type":"build","title":"Соберите время","items":[{"answer":["上午","九","点"],"hint":"«Девять утра.»"},{"answer":["下午","三","点"],"hint":"«Три часа дня.»"},{"answer":["什么","时候"],"hint":"«Когда?»"}]}'),
  ('hsk1-08-1', 9, 'write', '{"title":"Пропись","items":[{"hanzi":"午","pinyin":"wǔ","m":"полдень","hint":"сверху откидная, потом ═ и вертикаль"},{"hanzi":"上","pinyin":"shàng","m":"верх","hint":"вертикаль, потом две горизонтали"},{"hanzi":"下","pinyin":"xià","m":"низ","hint":"горизонталь, вертикаль, точка"}]}'),
  ('hsk1-08-1', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 中午?","options":["полдень","утро","вечер"],"correct":0},{"q":"Как читается 下午?","options":["xiàwǔ","xiāwǔ","xiàwú"],"correct":0},{"q":"Как сказать «девять утра»?","options":["上午九点","九点上午","上九午点"],"correct":0},{"q":"12 часов называют 十二点.","tf":true},{"q":"Что значит 时候?","options":["время, момент","час","минута"],"correct":0}]}'),
  ('hsk1-08-2', 1, 'fact', '{"emoji":"🚶","title":"Движение без предлогов","text":"По-русски мы говорим «иду В школу», «возвращаюсь ДОМОЙ». В китайском предлог не нужен: 去学校 «пойти школа», 回家 «вернуться дом». Три глагола движения: 来 «приходить сюда», 去 «идти туда», 回 «возвращаться». А 能 «мочь» ставится перед другим глаголом, как знакомое 会."}'),
  ('hsk1-08-2', 2, 'words', '{"title":"Четыре глагола","items":[{"hanzi":"来","pinyin":"lái","m":"приходить","emoji":"🚪","ex":{"zh":"你来学校吗？","py":"Nǐ lái xuéxiào ma?","m":"Ты придёшь в школу?"}},{"hanzi":"去","pinyin":"qù","m":"идти, ехать (туда)","emoji":"🚶","ex":{"zh":"我去商店。","py":"Wǒ qù shāngdiàn.","m":"Я иду в магазин."}},{"hanzi":"回","pinyin":"huí","m":"возвращаться","emoji":"🏠","ex":{"zh":"我回家。","py":"Wǒ huí jiā.","m":"Я иду домой."}},{"hanzi":"能","pinyin":"néng","m":"мочь, быть в состоянии","emoji":"💪","ex":{"zh":"你能来吗？","py":"Nǐ néng lái ma?","m":"Ты можешь прийти?"}}]}'),
  ('hsk1-08-2', 3, 'theory', '{"title":"Глагол + место","blocks":[{"t":"table","head":["Фраза","Пиньинь","Перевод"],"rows":[["我去学校。","Wǒ qù xuéxiào.","Я иду в школу."],["我回家。","Wǒ huí jiā.","Я иду домой."],["他来北京。","Tā lái Běijīng.","Он приезжает в Пекин."]]},{"t":"p","text":"来 используют, когда движение направлено к говорящему, 去 — от него. 回 — «вернуться» в привычное место (дом, школу)."},{"t":"tip","text":"Время стоит перед глаголом: 我明天去学校."}]}'),
  ('hsk1-08-2', 4, 'game', '{"type":"build","title":"Соберите предложение","items":[{"answer":["我","去","学校"],"hint":"«Я иду в школу.»"},{"answer":["我","回","家"],"hint":"«Я иду домой.»"},{"answer":["你","明天","来","吗"],"hint":"«Ты завтра придёшь?»"}]}'),
  ('hsk1-08-2', 5, 'quiz', '{"title":"Мини-тест: движение","qs":[{"q":"Как сказать «Я иду домой»?","options":["我回家。","我回到家。","我去在家。"],"correct":0},{"q":"Какой глагол значит «идти туда»?","options":["去","来","回"],"correct":0},{"q":"После 去 нужен предлог «в».","tf":false,"explain":"Китайский обходится без него."}]}'),
  ('hsk1-08-2', 6, 'theory', '{"title":"Скрытая фишка: 不 с глаголами движения","blocks":[{"t":"table","head":["Слово","Тон","С 不"],"rows":[["去 qù","4","不去 bú qù"],["来 lái","2","不来 bù lái"],["回 huí","2","不回 bù huí"],["能 néng","2","不能 bù néng"]]},{"t":"p","text":"Только перед 去 отрицание превращается в bú: это 4 тон. Во всех других случаях 不 остаётся bù."}]}'),
  ('hsk1-08-2', 7, 'game', '{"type":"listen","title":"Слушаем: 来, 去, 回, 能","items":[{"say":"去学校","options":["qù xuéxiào","lái xuéxiào"],"correct":0},{"say":"回家","options":["huí jiā","huì jiā"],"correct":0},{"say":"不去","options":["bú qù","bù qù"],"correct":0},{"say":"不来","options":["bù lái","bú lái"],"correct":0},{"say":"你能来吗","options":["nǐ néng lái ma","nǐ huì lái ma"],"correct":0}]}'),
  ('hsk1-08-2', 8, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["来","приходить"],["去","идти туда"],["回","возвращаться"],["能","мочь"],["回家","идти домой"]]}'),
  ('hsk1-08-2', 9, 'game', '{"type":"bughunt","title":"Китайский детектив: глаголы движения","cases":[{"buggyText":"我去在学校。","context":"«Я иду в школу»","options":["我去学校。","我在去学校。","我去的学校。"],"correct":0},{"buggyText":"我回去家。","context":"«Я иду домой»","options":["我回家。","我回在家。","我家回。"],"correct":0},{"buggyText":"你来能吗？","context":"«Ты можешь прийти?»","options":["你能来吗？","你来吗能？","能你来吗？"],"correct":0}]}'),
  ('hsk1-08-2', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 回?","options":["возвращаться","идти","приходить"],"correct":0},{"q":"Как читается 不去?","options":["bú qù","bù qù","bǔ qù"],"correct":0},{"q":"Как спросить «Ты можешь прийти?»","options":["你能来吗？","你来能吗？","你来吗能？"],"correct":0},{"q":"Перед 去 отрицание 不 читается bú.","tf":true},{"q":"Как сказать «Я завтра иду в школу»?","options":["我明天去学校。","我去明天学校。","明天学校我去。"],"correct":0}]}'),
  ('hsk1-08-3', 1, 'fact', '{"emoji":"👔","title":"«Родившийся раньше»","text":"先生 xiānsheng — «господин», «учитель», иногда и «муж». Буквально «родившийся раньше» (先 «раньше» + 生 «родиться»): уважительное обращение к старшим. 小姐 xiǎojiě — «госпожа, девушка»: «маленькая сестра». Слово 睡觉 «спать» разделяется: 觉 здесь читается jiào, а не jué."}'),
  ('hsk1-08-3', 2, 'words', '{"title":"Работа, сон, обращения","items":[{"hanzi":"睡觉","pinyin":"shuìjiào","m":"спать","emoji":"😴","ex":{"zh":"我十点睡觉。","py":"Wǒ shí diǎn shuìjiào.","m":"Я ложусь спать в десять."}},{"hanzi":"工作","pinyin":"gōngzuò","m":"работать, работа","emoji":"💼","ex":{"zh":"我下午工作。","py":"Wǒ xiàwǔ gōngzuò.","m":"Я работаю днём."}},{"hanzi":"先生","pinyin":"xiānsheng","m":"господин, Вы (к мужчине)","emoji":"👨‍💼","ex":{"zh":"王先生，您好！","py":"Wáng xiānsheng, nín hǎo!","m":"Здравствуйте, господин Ван!"}},{"hanzi":"小姐","pinyin":"xiǎojiě","m":"госпожа, девушка","emoji":"👩‍💼","ex":{"zh":"李小姐，您好！","py":"Lǐ xiǎojiě, nín hǎo!","m":"Здравствуйте, госпожа Ли!"}}]}'),
  ('hsk1-08-3', 3, 'game', '{"type":"listen","title":"Слушаем: работа и обращения","items":[{"say":"睡觉","options":["shuìjiào","shuǐjiào","shuìjué"],"correct":0},{"say":"工作","options":["gōngzuò","gōngzuǒ","góngzuò"],"correct":0},{"say":"先生","options":["xiānsheng","xiānshēng","xiánsheng"],"correct":0},{"say":"小姐","options":["xiǎojiě","xiǎojiè","xiáojiě"],"correct":0},{"say":"王先生，您好","options":["Wáng xiānsheng, nín hǎo","Wáng xiǎojiě, nín hǎo"],"correct":0}]}'),
  ('hsk1-08-3', 4, 'game', '{"type":"tone_visualizer","initialTone":1,"title":"Тренажёр голоса: повторите «gōng» (1 тон)"}'),
  ('hsk1-08-3', 5, 'theory', '{"title":"Как обращаться к людям","blocks":[{"t":"table","head":["Обращение","Когда"],"rows":[["王先生","господин Ван (к мужчине)"],["李小姐","госпожа Ли (к девушке)"],["王老师","учитель Ван"]]},{"t":"p","text":"Фамилия идёт перед обращением: 王先生, 李小姐, 王老师. К 先生 и 小姐 лучше добавлять 您, чтобы звучать вежливо."}]}'),
  ('hsk1-08-3', 6, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"😴","options":["睡觉","工作","来"],"correct":0},{"emoji":"💼","options":["工作","睡觉","回"],"correct":0},{"emoji":"👨‍💼","options":["先生","小姐","老师"],"correct":0},{"emoji":"👩‍💼","options":["小姐","先生","学生"],"correct":0}]}'),
  ('hsk1-08-3', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["睡觉","спать"],["工作","работать"],["先生","господин"],["小姐","госпожа"],["王先生","господин Ван"]]}'),
  ('hsk1-08-3', 8, 'game', '{"type":"chatsim","title":"WeChat: распорядок","messages":[{"speaker":"Ли Мин","text":"你下午工作吗？","pinyin":"Nǐ xiàwǔ gōngzuò ma?","translation":"Ты днём работаешь?","options":["工作，我三点来。","工作，我三点睡。","不工作，我是工作。"],"correct":0},{"speaker":"Ли Мин","text":"你几点睡觉？","pinyin":"Nǐ jǐ diǎn shuìjiào?","translation":"Во сколько ты ложишься спать?","options":["我十点睡觉。","我十个睡觉。","我十号睡觉。"],"correct":0},{"speaker":"Ли Мин","text":"王先生好！","pinyin":"Wáng xiānsheng hǎo!","translation":"Здравствуйте, господин Ван!","options":["您好！","再见！","不客气。"],"correct":0}]}'),
  ('hsk1-08-3', 9, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","下午","工作"],"hint":"«Днём я работаю.»"},{"answer":["我","十","点","睡觉"],"hint":"«В десять я ложусь спать.»"},{"answer":["王","先生","您好"],"hint":"«Здравствуйте, господин Ван!»"}]}'),
  ('hsk1-08-3', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 睡觉?","options":["спать","работать","приходить"],"correct":0},{"q":"Как читается 先生?","options":["xiānsheng","xiānshēng","xiǎnsheng"],"correct":0},{"q":"先生 буквально «родившийся раньше».","tf":true},{"q":"Как сказать «господин Ван»?","options":["王先生","先生王","王的先生"],"correct":0},{"q":"Что значит 小姐?","options":["госпожа, девушка","господин","учитель"],"correct":0}]}'),
  ('hsk1-08-4', 1, 'fact', '{"emoji":"📱","title":"Договорённость в чате","text":"Анна и Ли Мин решают, когда они придут в школу завтра. Все слова уже знакомы."}'),
  ('hsk1-08-4', 2, 'text', '{"title":"Договариваемся на завтра","lines":[{"zh":"李明：安娜，你明天上午来学校吗？","py":"Lǐ Míng: Ānnà, nǐ míngtiān shàngwǔ lái xuéxiào ma?","m":"Ли Мин: Анна, ты завтра утром придёшь в школу?"},{"zh":"安娜：不来。我下午去学校。","py":"Ānnà: Bù lái. Wǒ xiàwǔ qù xuéxiào.","m":"Анна: Нет. Я приду днём."},{"zh":"李明：什么时候？","py":"Lǐ Míng: Shénme shíhou?","m":"Ли Мин: Во сколько?"},{"zh":"安娜：下午三点。你能来吗？","py":"Ānnà: Xiàwǔ sān diǎn. Nǐ néng lái ma?","m":"Анна: В три часа дня. Ты можешь прийти?"},{"zh":"李明：能！我三点去学校。","py":"Lǐ Míng: Néng! Wǒ sān diǎn qù xuéxiào.","m":"Ли Мин: Могу! Я приду в три."},{"zh":"安娜：好，明天见！","py":"Ānnà: Hǎo, míngtiān jiàn!","m":"Анна: Хорошо, до завтра!"},{"zh":"李明：明天见！","py":"Lǐ Míng: Míngtiān jiàn!","m":"Ли Мин: До завтра!"}],"qs":[{"q":"Когда Анна придёт в школу?","options":["днём в три","утром","в полдень"],"correct":0},{"q":"Анна придёт в школу утром.","tf":false,"explain":"Она говорит 不来 про утро."},{"q":"Что отвечает Ли Мин на вопрос 你能来吗？","options":["能","不能","不去"],"correct":0},{"q":"Вставьте слово: 我下午___学校。","options":["去","来","回"],"correct":0},{"q":"Ли Мин тоже пойдёт в школу в три часа.","tf":true},{"q":"Как Ли Мин спрашивает про время?","options":["什么时候？","几个？","几号？"],"correct":0},{"q":"Чем заканчивается диалог?","options":["明天见","对不起","不客气"],"correct":0}]}'),
  ('hsk1-08-4', 3, 'game', '{"type":"match","title":"Фраза и смысл","pairs":[["你能来吗？","Ты можешь прийти?"],["不来","не приду"],["下午三点","в три часа дня"],["明天见","до завтра"],["什么时候？","когда?"]]}'),
  ('hsk1-08-4', 4, 'game', '{"type":"listen","title":"Слышим реплики","items":[{"say":"你明天上午来学校吗","options":["nǐ míngtiān shàngwǔ lái xuéxiào ma","nǐ míngtiān xiàwǔ lái xuéxiào ma"],"correct":0},{"say":"我下午去学校","options":["wǒ xiàwǔ qù xuéxiào","wǒ shàngwǔ qù xuéxiào"],"correct":0},{"say":"你能来吗","options":["nǐ néng lái ma","nǐ huì lái ma"],"correct":0},{"say":"明天见","options":["míngtiān jiàn","míngtiān zàijiàn"],"correct":0}]}'),
  ('hsk1-08-4', 5, 'game', '{"type":"bughunt","title":"Китайский детектив: план","cases":[{"buggyText":"我下午学校去。","context":"«Днём я иду в школу»","options":["我下午去学校。","下午我学校去。","去我下午学校。"],"correct":0},{"buggyText":"你能不来吗？","context":"«Ты можешь прийти?»","options":["你能来吗？","你来能吗？","能来你吗？"],"correct":0},{"buggyText":"我三点来去学校。","context":"«В три я иду в школу»","options":["我三点去学校。","我去三点学校。","三点学校去我。"],"correct":0}]}'),
  ('hsk1-08-4', 6, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «Днём я иду домой»?","options":["我下午回家。","我回下午家。","下午回我家。"],"correct":0},{"q":"Как читается 不来?","options":["bù lái","bú lái","bǔ lái"],"correct":0},{"q":"Ли Мин и Анна встретятся в три часа.","tf":true}]}'),
  ('hsk1-08-5', 1, 'fact', '{"emoji":"🗓️","title":"Расскажите о своём дне","text":"Составьте расписание дня и расскажите, когда вы работаете, учитесь и спите. Слова глав 1–8."}'),
  ('hsk1-08-5', 2, 'game', '{"type":"radical_puzzle","hanzi":"睡","correctRadicals":["目","垂"],"title":"Пазл: соберите 睡"}'),
  ('hsk1-08-5', 3, 'game', '{"type":"radical_build","title":"Сборка знаков","items":[{"targetHanzi":"睡","radicals":["目","垂","口"],"correctOrder":["目","垂"],"explain":"Слева 目 «глаз», справа 垂."},{"targetHanzi":"工","radicals":["一","丨","口"],"correctOrder":["一","丨","一"],"explain":"Три черты: верхняя, вертикаль, нижняя."},{"targetHanzi":"回","radicals":["囗","口","日"],"correctOrder":["囗","口"],"explain":"Рамка и внутри 口."}]}'),
  ('hsk1-08-5', 4, 'game', '{"type":"build","title":"Мастерская расписания","items":[{"target":"(Расписание)","answer":["上午","我","去","学校"],"hint":"«Утром я иду в школу.»"},{"target":"(Расписание)","answer":["中午","我","回","家"],"hint":"«В полдень я иду домой.»"},{"target":"(Расписание)","answer":["下午","我","工作"],"hint":"«Днём я работаю.»"},{"target":"(Расписание)","answer":["我","十","点","睡觉"],"hint":"«В десять я ложусь спать.»"}]}'),
  ('hsk1-08-5', 5, 'theory', '{"title":"Образец рассказа о дне","blocks":[{"t":"table","head":["Время","Фраза"],"rows":[["Утро","上午我去学校。"],["Полдень","中午我回家。"],["День","下午我工作。"],["Ночь","十点我睡觉。"]]}]}'),
  ('hsk1-08-5', 6, 'game', '{"type":"chatsim","title":"WeChat: мой день","messages":[{"speaker":"Друг","text":"你上午做什么？","pinyin":"Nǐ shàngwǔ zuò shénme?","translation":"Что ты делаешь утром? (做 «делать» — новое слово)","options":["我去学校。","我是学校。","我叫学校。"],"correct":0},{"speaker":"Друг","text":"你几点回家？","pinyin":"Nǐ jǐ diǎn huí jiā?","translation":"Во сколько ты идёшь домой?","options":["我五点回家。","我五个回家。","我五号回家。"],"correct":0},{"speaker":"Друг","text":"你几点睡觉？","pinyin":"Nǐ jǐ diǎn shuìjiào?","translation":"Во сколько ты ложишься спать?","options":["我十点睡觉。","我十个睡觉。","我十岁睡觉。"],"correct":0}]}'),
  ('hsk1-08-5', 7, 'game', '{"type":"match","title":"Знак и смысл","pairs":[["目 + 垂","睡"],["囗 + 口","回"],["上午","утро"],["下午","день"]]}'),
  ('hsk1-08-5', 8, 'write', '{"title":"Пропись: движение","items":[{"hanzi":"回","pinyin":"huí","m":"возвращаться","hint":"рамка, внутри ещё одна рамка"},{"hanzi":"去","pinyin":"qù","m":"идти","hint":"сверху 土, снизу 厶"},{"hanzi":"来","pinyin":"lái","m":"приходить","hint":"сверху 一, потом 木 с двумя точками"}]}'),
  ('hsk1-08-5', 9, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «В десять я ложусь спать»?","options":["我十点睡觉。","我睡觉十点。","十我点睡觉。"],"correct":0},{"q":"Какой глагол значит «вернуться»?","options":["回","去","来"],"correct":0},{"q":"上午, 中午 и 下午 стоят перед глаголом.","tf":true}]}'),
  ('hsk1-08-6', 1, 'fact', '{"emoji":"🏁","title":"Экзамен главы 8","text":"Части дня, глаголы 来, 去, 回, 能, работа и сон, обращения 先生 и 小姐."}'),
  ('hsk1-08-6', 2, 'game', '{"type":"listen","title":"Аудирование","items":[{"say":"上午","options":["shàngwǔ","xiàwǔ","zhōngwǔ"],"correct":0},{"say":"下午三点","options":["xiàwǔ sān diǎn","shàngwǔ sān diǎn"],"correct":0},{"say":"我回家","options":["wǒ huí jiā","wǒ qù jiā"],"correct":0},{"say":"不去","options":["bú qù","bù qù"],"correct":0},{"say":"你能来吗","options":["nǐ néng lái ma","nǐ huì lái ma"],"correct":0},{"say":"王先生","options":["Wáng xiānsheng","Wáng xiǎojiě"],"correct":0}]}'),
  ('hsk1-08-6', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🌅","options":["上午","中午","下午"],"correct":0},{"emoji":"🚶","options":["去","来","回"],"correct":0},{"emoji":"😴","options":["睡觉","工作","能"],"correct":0},{"emoji":"💼","options":["工作","睡觉","先生"],"correct":0}]}'),
