  ('hsk1-08-6', 5, 'quiz', '{"title":"Экзаменационные вопросы","qs":[{"q":"Как сказать «Днём я иду домой»?","options":["我下午回家。","我回下午家。","下午回我家。"],"correct":0},{"q":"Как читается 不去?","options":["bú qù","bù qù","bǔ qù"],"correct":0},{"q":"Как спросить «Когда?»","options":["什么时候？","几时候？","时候什么？"],"correct":0},{"q":"Перед глаголом ставят слово времени.","tf":true},{"q":"Как сказать «Ты можешь прийти?»","options":["你能来吗？","你来能吗？","吗你能来？"],"correct":0},{"q":"Что значит 先生?","options":["господин","госпожа","учитель"],"correct":0},{"q":"После 去 нужен предлог.","tf":false},{"q":"Как сказать «В десять я ложусь спать»?","options":["我十点睡觉。","我睡觉十点。","十点我睡。"],"correct":0},{"q":"Как читается 不来?","options":["bù lái","bú lái","bǔ lái"],"correct":0},{"q":"Что значит 工作?","options":["работать","спать","возвращаться"],"correct":0}]}'),
  ('hsk1-08-6', 6, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","去","学校"],"hint":"«Я иду в школу.»"},{"answer":["我","回","家"],"hint":"«Я иду домой.»"},{"answer":["下午","三","点","我","工作"],"hint":"«В три часа дня я работаю.»"},{"answer":["你","能","来","吗"],"hint":"«Ты можешь прийти?»"}]}'),
  ('hsk1-08-6', 7, 'game', '{"type":"bughunt","title":"Найдите ошибку","cases":[{"buggyText":"我去在学校。","context":"«Я иду в школу»","options":["我去学校。","我在去学校。","我去的学校。"],"correct":0},{"buggyText":"我回去家。","context":"«Я иду домой»","options":["我回家。","我回在家。","我家回。"],"correct":0},{"buggyText":"你来能吗？","context":"«Ты можешь прийти?»","options":["你能来吗？","你来吗能？","能你来吗？"],"correct":0}]}'),
  ('hsk1-08-6', 8, 'game', '{"type":"chatsim","title":"Мини-чат","messages":[{"speaker":"Друг","text":"你明天来学校吗？","pinyin":"Nǐ míngtiān lái xuéxiào ma?","translation":"Ты завтра придёшь в школу?","options":["来，下午三点。","来，是下午。","不是，我来。"],"correct":0},{"speaker":"Друг","text":"好，明天见！","pinyin":"Hǎo, míngtiān jiàn!","translation":"Хорошо, до завтра!","options":["明天见！","对不起！","没关系。"],"correct":0}]}'),
  ('hsk1-08-6', 9, 'write', '{"title":"Пропись по памяти","items":[{"hanzi":"午","pinyin":"wǔ","m":"полдень","hint":"откидная, две горизонтали, вертикаль"},{"hanzi":"回","pinyin":"huí","m":"возвращаться","hint":"рамка в рамке"},{"hanzi":"来","pinyin":"lái","m":"приходить","hint":"木 с чертой"}]}'),
  ('hsk1-08-6', 10, 'recall', '{"words":[{"hanzi":"上午","pinyin":"shàngwǔ","m":"утро"},{"hanzi":"中午","pinyin":"zhōngwǔ","m":"полдень"},{"hanzi":"下午","pinyin":"xiàwǔ","m":"день после полудня"},{"hanzi":"时候","pinyin":"shíhou","m":"время"},{"hanzi":"来","pinyin":"lái","m":"приходить"},{"hanzi":"去","pinyin":"qù","m":"идти"},{"hanzi":"回","pinyin":"huí","m":"возвращаться"},{"hanzi":"能","pinyin":"néng","m":"мочь"},{"hanzi":"睡觉","pinyin":"shuìjiào","m":"спать"},{"hanzi":"工作","pinyin":"gōngzuò","m":"работать"},{"hanzi":"先生","pinyin":"xiānsheng","m":"господин"},{"hanzi":"小姐","pinyin":"xiǎojiě","m":"госпожа"}],"tf":[{"zh":"我去在学校。","py":"wǒ qù zài xuéxiào.","m":"Я иду в школу.","ok":false,"explain":"Правильно: 我去学校."},{"zh":"我回家。","py":"wǒ huí jiā.","m":"Я иду домой.","ok":true}],"sentences":[{"zh":"我下午去学校。","tokens":["我","下午","去","学校"],"m":"Днём я иду в школу."},{"zh":"你能来吗？","tokens":["你","能","来","吗"],"m":"Ты можешь прийти?"},{"zh":"我十点睡觉。","tokens":["我","十","点","睡觉"],"m":"В десять я ложусь спать."}]}'),
  ('hsk1-09-1', 1, 'fact', '{"emoji":"🍚","title":"Обед — это «рис плюс блюда»","text":"У китайцев еда делится на две части: 饭 «основа» (рис, лапша) и 菜 «блюда к ней» (овощи, мясо). Поэтому 米饭 — «варёный рис», 吃饭 — буквально «есть основу», то есть «обедать», а 菜 — и «овощи», и «блюдо». Знаки 吃 «есть» и 喝 «пить» оба начинаются с 口 «рот»."}'),
  ('hsk1-09-1', 2, 'words', '{"title":"Еда и глаголы","items":[{"hanzi":"吃","pinyin":"chī","m":"есть","emoji":"😋","ex":{"zh":"我吃米饭。","py":"Wǒ chī mǐfàn.","m":"Я ем рис."}},{"hanzi":"喝","pinyin":"hē","m":"пить","emoji":"🥤","ex":{"zh":"你喝什么？","py":"Nǐ hē shénme?","m":"Что ты пьёшь?"}},{"hanzi":"米饭","pinyin":"mǐfàn","m":"варёный рис","emoji":"🍚","ex":{"zh":"我想吃米饭。","py":"Wǒ xiǎng chī mǐfàn.","m":"Я хочу рис."}},{"hanzi":"菜","pinyin":"cài","m":"овощи, блюдо","emoji":"🥬","ex":{"zh":"这个菜很好。","py":"Zhège cài hěn hǎo.","m":"Это блюдо очень хорошее."}}]}'),
  ('hsk1-09-1', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🍚","options":["菜","米饭","吃"],"correct":1},{"emoji":"🥬","options":["米饭","喝","菜"],"correct":2},{"emoji":"😋","options":["吃","喝","菜"],"correct":0},{"emoji":"🥤","options":["吃","菜","喝"],"correct":2}]}'),
  ('hsk1-09-1', 4, 'theory', '{"title":"吃 и 喝: что с чем","blocks":[{"t":"table","head":["Глагол","Что можно","Пример"],"rows":[["吃 chī","еда: рис, овощи","吃米饭, 吃菜"],["喝 hē","напитки","喝水, 喝茶"]]},{"t":"p","text":"Глагол ставится перед тем, что едят или пьют: 吃米饭, 喝茶. Перепутать глаголы нельзя: воду «не едят»."},{"t":"tip","text":"Оба слога 吃 chī и 喝 hē — в первом тоне: ровный и высокий."}]}'),
  ('hsk1-09-1', 5, 'quiz', '{"title":"Мини-тест: еда","qs":[{"q":"Какой глагол сочетается с 米饭?","options":["喝","吃","买"],"correct":1},{"q":"喝 используют с едой, например 喝米饭.","tf":false,"explain":"С едой нужен 吃."},{"q":"Какой ключ в знаках 吃 и 喝?","options":["亻","女","口"],"correct":2}]}'),
  ('hsk1-09-1', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["吃","есть"],["喝","пить"],["米饭","варёный рис"],["菜","овощи, блюдо"],["吃米饭","есть рис"]]}'),
  ('hsk1-09-1', 7, 'game', '{"type":"listen","title":"Слушаем: еда и глаголы","items":[{"say":"吃","options":["chí","chī","chǐ"],"correct":1},{"say":"喝","options":["hē","hè","hé"],"correct":0},{"say":"米饭","options":["mífàn","mǐfàn","mǐfān"],"correct":1},{"say":"菜","options":["cǎi","cāi","cài"],"correct":2},{"say":"我吃米饭","options":["wǒ hē mǐfàn","wǒ chī mǐfàn"],"correct":1}]}'),
  ('hsk1-09-1', 8, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","吃","米饭"],"hint":"«Я ем рис.»"},{"answer":["我","吃","菜"],"hint":"«Я ем овощи.»"},{"answer":["你","喝","什么"],"hint":"«Что ты пьёшь?»"}]}'),
  ('hsk1-09-1', 9, 'write', '{"title":"Пропись: еда","items":[{"hanzi":"吃","pinyin":"chī","m":"есть","hint":"слева 口, справа 乞"},{"hanzi":"喝","pinyin":"hē","m":"пить","hint":"слева 口, справа 曷"},{"hanzi":"菜","pinyin":"cài","m":"овощи","hint":"сверху 艹, снизу 采"}]}'),
  ('hsk1-09-1', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 菜?","options":["рис","овощи, блюдо","пить"],"correct":1},{"q":"Как читается 吃?","options":["chī","chǐ","chí"],"correct":0},{"q":"Как сказать «Я ем рис»?","options":["我喝米饭。","米饭吃我。","我吃米饭。"],"correct":2},{"q":"米饭 — это варёный рис.","tf":true},{"q":"Что значит 喝?","options":["пить","есть","покупать"],"correct":0}]}'),
  ('hsk1-09-2', 1, 'fact', '{"emoji":"💧","title":"Знак 水 — это ручей","text":"Иероглиф 水 «вода» нарисован как течение с брызгами по бокам. В сложных знаках у воды есть сокращённая форма 氵 (три капли слева). Вы встречали её в 汉. А 茶 «чай» — это 艹 «трава» над 人 «человек» и 木 «дерево»: человек среди листьев и ветвей."}'),
  ('hsk1-09-2', 2, 'words', '{"title":"Два напитка","items":[{"hanzi":"水","pinyin":"shuǐ","m":"вода","emoji":"💧","ex":{"zh":"我喝水。","py":"Wǒ hē shuǐ.","m":"Я пью воду."}},{"hanzi":"茶","pinyin":"chá","m":"чай","emoji":"🍵","ex":{"zh":"你喝茶吗？","py":"Nǐ hē chá ma?","m":"Ты пьёшь чай?"}}]}'),
  ('hsk1-09-2', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"💧","options":["茶","水","喝"],"correct":1},{"emoji":"🍵","options":["茶","水","菜"],"correct":0}]}'),
  ('hsk1-09-2', 4, 'theory', '{"title":"Вопросы с 什么 и с 吗","blocks":[{"t":"table","head":["Вопрос","Ответ"],"rows":[["你吃什么？","我吃米饭。"],["你喝什么？","我喝水。"],["你喝茶吗？","喝。 / 不喝。"]]},{"t":"p","text":"Чтобы ответить «да» или «нет», повторяют глагол: 喝 или 不喝. Вспомните: 什么 встаёт на место ответа и 吗 не нужен."},{"t":"tip","text":"И 吃, и 喝 в первом тоне, поэтому 不 остаётся bù: 不吃 bù chī, 不喝 bù hē."}]}'),
  ('hsk1-09-2', 5, 'game', '{"type":"build","title":"Соберите предложение","items":[{"answer":["你","喝","什么"],"hint":"«Что ты пьёшь?»"},{"answer":["我","喝","茶"],"hint":"«Я пью чай.»"},{"answer":["你","喝","茶","吗"],"hint":"«Ты пьёшь чай?»"},{"answer":["我","不","喝","水"],"hint":"«Я не пью воду.»"}]}'),
  ('hsk1-09-2', 6, 'quiz', '{"title":"Мини-тест: ответы","qs":[{"q":"Как ответить «нет» на 你喝茶吗？","options":["不是。","不喝。","没有。"],"correct":1},{"q":"Как читается 不喝?","options":["bú hē","bǔ hē","bù hē"],"correct":2},{"q":"К вопросу 你喝什么？ добавляют 吗.","tf":false,"explain":"Вопросительное слово 什么 заменяет 吗."}]}'),
  ('hsk1-09-2', 7, 'theory', '{"title":"Перечисляем: 和","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["米饭和菜","рис и овощи"],["水和茶","вода и чай"],["我吃米饭和菜。","Я ем рис и овощи."]]},{"t":"p","text":"和 соединяет предметы, а не действия. Два глагола одним 和 не связывают."}]}'),
  ('hsk1-09-2', 8, 'game', '{"type":"listen","title":"Слушаем: вода и чай","items":[{"say":"水","options":["shuí","shuǐ","shuì"],"correct":1},{"say":"茶","options":["chá","chà","chǎ"],"correct":0},{"say":"不喝","options":["bú hē","bù hē"],"correct":1},{"say":"你喝茶吗","options":["nǐ hē chá ma","nǐ chī chá ma"],"correct":0},{"say":"我喝水","options":["wǒ chī shuǐ","wǒ hē shuǐ"],"correct":1}]}'),
  ('hsk1-09-2', 9, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["水","вода"],["茶","чай"],["不喝","не пью"],["你喝什么？","Что ты пьёшь?"],["米饭和菜","рис и овощи"]]}'),
  ('hsk1-09-2', 10, 'game', '{"type":"bughunt","title":"Китайский детектив: еда и напитки","cases":[{"buggyText":"我吃水。","context":"«Я пью воду»","options":["我喝水。","我水喝。","喝我水。"],"correct":0,"explain":"Воду пьют, а не едят."},{"buggyText":"你喝什么吗？","context":"«Что ты пьёшь?»","options":["你吗喝什么？","你喝什么？","什么你喝吗？"],"correct":1},{"buggyText":"我吃米饭吃菜。","context":"«Я ем рис и овощи»","options":["我吃米饭有菜。","我吃饭菜和。","我吃米饭和菜。"],"correct":2}]}'),
  ('hsk1-09-2', 11, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «чай»?","options":["水","菜","茶"],"correct":2},{"q":"Как сказать «Я пью воду»?","options":["我喝水。","我吃水。","水我吃。"],"correct":0},{"q":"喝 и 吃 читаются в первом тоне.","tf":true},{"q":"Как спросить «Ты пьёшь чай?»","options":["你茶喝吗？","你喝茶吗？","你吗喝茶？"],"correct":1},{"q":"Что значит 水?","options":["чай","вода","рис"],"correct":1}]}'),
  ('hsk1-09-3', 1, 'fact', '{"emoji":"🍎","title":"Яблоко — пожелание мира","text":"苹果 píngguǒ звучит почти как 平安 píng''ān «мир и безопасность». Поэтому в канун Рождества китайцы дарят друг другу яблоки (平安夜 «ночь мира»). 水果 «фрукты» — буквально «водяной плод». А 饭店 — «ресторан», а часто и «большой отель»."}'),
  ('hsk1-09-3', 2, 'words', '{"title":"Четыре слова","items":[{"hanzi":"苹果","pinyin":"píngguǒ","m":"яблоко","emoji":"🍎","ex":{"zh":"我吃苹果。","py":"Wǒ chī píngguǒ.","m":"Я ем яблоко."}},{"hanzi":"水果","pinyin":"shuǐguǒ","m":"фрукты","emoji":"🍇","ex":{"zh":"我喜欢水果。","py":"Wǒ xǐhuan shuǐguǒ.","m":"Я люблю фрукты."}},{"hanzi":"饭店","pinyin":"fàndiàn","m":"ресторан, отель","emoji":"🏨","ex":{"zh":"我们去饭店。","py":"Wǒmen qù fàndiàn.","m":"Мы идём в ресторан."}},{"hanzi":"杯子","pinyin":"bēizi","m":"стакан, чашка","emoji":"🥛","ex":{"zh":"一个杯子","py":"yí gè bēizi","m":"один стакан"}}]}'),
  ('hsk1-09-3', 3, 'game', '{"type":"listen","title":"Слушаем: фрукты и ресторан","items":[{"say":"苹果","options":["píngguǒ","pínggǔo","píngguò"],"correct":0},{"say":"水果","options":["shuíguǒ","shuǐguǒ","shuǐguó"],"correct":1},{"say":"饭店","options":["fàndiàn","fāndiàn","fàndián"],"correct":0},{"say":"杯子","options":["bēizi","bèizi","běizi"],"correct":0},{"say":"我们去饭店","options":["wǒmen qù fàndiàn","wǒmen huí fàndiàn"],"correct":0}]}'),
  ('hsk1-09-3', 4, 'game', '{"type":"tone_visualizer","initialTone":2,"title":"Тренажёр голоса: повторите «píng» (2 тон)"}'),
  ('hsk1-09-3', 5, 'theory', '{"title":"Измерение напитков: 一杯","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["一杯水","стакан воды"],["一杯茶","чашка чая"],["一个苹果","одно яблоко"]]},{"t":"p","text":"Для жидкостей используют 杯 «стакан, чашка» вместо 个: 一杯茶. Перед 杯 четвёртого тона 一 читается yì: yì bēi (杯 в 1 тоне)."},{"t":"tip","text":"Для фруктов подходит 个: 一个苹果 yí gè píngguǒ."}]}'),
  ('hsk1-09-3', 6, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🍎","options":["饭店","苹果","杯子"],"correct":1},{"emoji":"🍇","options":["水果","苹果","茶"],"correct":0},{"emoji":"🏨","options":["杯子","水果","饭店"],"correct":2},{"emoji":"🥛","options":["杯子","水","菜"],"correct":0}]}'),
  ('hsk1-09-3', 7, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["苹果","яблоко"],["水果","фрукты"],["饭店","ресторан, отель"],["杯子","стакан, чашка"],["一杯茶","чашка чая"]]}'),
  ('hsk1-09-3', 8, 'game', '{"type":"chatsim","title":"В ресторане","messages":[{"speaker":"Официант","text":"你们喝什么？","pinyin":"Nǐmen hē shénme?","translation":"Что вы будете пить?","options":["我喝一杯茶。","我吃一杯茶。","我茶是一杯。"],"correct":0,"explain":"Для жидкости — 杯."},{"speaker":"Официант","text":"你吃什么？","pinyin":"Nǐ chī shénme?","translation":"Что вы будете есть?","options":["我喝米饭。","我吃米饭和菜。","我杯子米饭。"],"correct":1},{"speaker":"Официант","text":"你吃水果吗？","pinyin":"Nǐ chī shuǐguǒ ma?","translation":"Вы будете фрукты?","options":["不吃，我吃菜。","不喝，我是水果。","我没有水果的。"],"correct":0}]}'),
  ('hsk1-09-3', 9, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","喝","一","杯","水"],"hint":"«Я пью стакан воды.»"},{"answer":["我","吃","一个","苹果"],"hint":"«Я ем яблоко.»"},{"answer":["我们","去","饭店"],"hint":"«Мы идём в ресторан.»"}]}'),
  ('hsk1-09-3', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 水果?","options":["фрукты","вода","яблоко"],"correct":0},{"q":"Какое слово подходит для «стакан»?","options":["苹果","杯子","饭店"],"correct":1},{"q":"饭店 может значить и «ресторан», и «отель».","tf":true},{"q":"Как читается 苹果?","options":["píngguǒ","pínggǔo","píngguò"],"correct":0},{"q":"Как сказать «чашка чая»?","options":["一个茶","一茶杯","一杯茶"],"correct":2}]}'),
  ('hsk1-09-4', 1, 'fact', '{"emoji":"🍽️","title":"Мамин вопрос: «Что ты будешь есть?»","text":"Китайские мамы кормят детей без пауз. Мама Ли Мина предлагает и еду, и напитки, и фрукты. Читайте, как он выбирает."}'),
  ('hsk1-09-4', 2, 'text', '{"title":"Ужин дома","lines":[{"zh":"妈妈：李明，你吃什么？","py":"Māma: Lǐ Míng, nǐ chī shénme?","m":"Мама: Ли Мин, что ты будешь есть?"},{"zh":"李明：我吃米饭和菜。","py":"Lǐ Míng: Wǒ chī mǐfàn hé cài.","m":"Ли Мин: Я буду рис и овощи."},{"zh":"妈妈：你喝什么？","py":"Māma: Nǐ hē shénme?","m":"Мама: Что ты будешь пить?"},{"zh":"李明：我喝水。","py":"Lǐ Míng: Wǒ hē shuǐ.","m":"Ли Мин: Я буду воду."},{"zh":"妈妈：你喝茶吗？","py":"Māma: Nǐ hē chá ma?","m":"Мама: Ты будешь чай?"},{"zh":"李明：不喝。","py":"Lǐ Míng: Bù hē.","m":"Ли Мин: Не буду."},{"zh":"妈妈：吃苹果吗？","py":"Māma: Chī píngguǒ ma?","m":"Мама: Будешь яблоко?"},{"zh":"李明：吃！谢谢妈妈！","py":"Lǐ Míng: Chī! Xièxie māma!","m":"Ли Мин: Буду! Спасибо, мама!"}],"qs":[{"q":"Что ест Ли Мин?","options":["рис и овощи","яблоко и чай","только рис"],"correct":0},{"q":"Ли Мин пьёт чай.","tf":false,"explain":"Он говорит 不喝."},{"q":"Что он пьёт?","options":["чай","воду","ничего"],"correct":1},{"q":"Вставьте слово: 你喝___吗？","options":["米饭","菜","茶"],"correct":2},{"q":"Ли Мин соглашается съесть яблоко.","tf":true},{"q":"Как Ли Мин отвечает «да» на вопрос о яблоке?","options":["喝","吃","是"],"correct":1},{"q":"Как Ли Мин благодарит маму?","options":["对不起，妈妈","谢谢妈妈","再见，妈妈"],"correct":1}]}'),
  ('hsk1-09-4', 3, 'game', '{"type":"match","title":"Реплика и смысл","pairs":[["我吃米饭和菜","Я ем рис и овощи"],["我喝水","Я пью воду"],["不喝","Не буду пить"],["吃苹果吗？","Будешь яблоко?"],["谢谢妈妈","Спасибо, мама"]]}'),
  ('hsk1-09-4', 4, 'game', '{"type":"listen","title":"Слышим реплики","items":[{"say":"你吃什么","options":["nǐ chī shénme","nǐ hē shénme"],"correct":0},{"say":"我喝水","options":["wǒ hē shuǐ","wǒ chī shuǐ"],"correct":0},{"say":"不喝","options":["bú hē","bù hē"],"correct":1},{"say":"吃苹果吗","options":["hē píngguǒ ma","chī píngguǒ ma"],"correct":1}]}'),
  ('hsk1-09-4', 5, 'game', '{"type":"bughunt","title":"Китайский детектив: за столом","cases":[{"buggyText":"我吃茶。","context":"Сказать «Я пью чай»","options":["我喝茶。","我茶吃。","吃我茶。"],"correct":0},{"buggyText":"我吃米饭菜。","context":"«Я ем рис и овощи»","options":["我吃米饭有菜。","我吃米饭和菜。","我米饭和菜吃。"],"correct":1},{"buggyText":"不吃苹果吗？","context":"Спросить «Будешь яблоко?»","options":["苹果吃吗？","吃吗苹果？","吃苹果吗？"],"correct":2}]}'),
