  ('hsk1-09-5', 6, 'game', '{"type":"chatsim","title":"В ресторане: сделайте заказ","messages":[{"speaker":"Официант","text":"你吃什么？","pinyin":"Nǐ chī shénme?","translation":"Что вы будете есть?","options":["我吃水。","我吃米饭。","我喝米饭。"],"correct":1},{"speaker":"Официант","text":"你喝什么？","pinyin":"Nǐ hē shénme?","translation":"Что вы будете пить?","options":["我喝茶。","我吃茶。","我茶是喝。"],"correct":0},{"speaker":"Официант","text":"还要什么？","pinyin":"Hái yào shénme?","translation":"Что-нибудь ещё? (还要 «ещё хотите» — новое выражение)","options":["我吃苹果。","我是苹果。","苹果杯子。"],"correct":0}]}'),
