  ('hsk1-09-6', 1, 'fact', '{"emoji":"🏁","title":"Экзамен главы 9","text":"Еда, напитки, 吃 и 喝, 一杯 и вопросы за столом."}'),
  ('hsk1-09-6', 2, 'game', '{"type":"listen","title":"Аудирование","items":[{"say":"米饭","options":["mǐfàn","mífàn","mǐfān"],"correct":0},{"say":"我吃菜","options":["wǒ hē cài","wǒ chī cài"],"correct":1},{"say":"喝水","options":["hē shuǐ","chī shuǐ"],"correct":0},{"say":"苹果","options":["píngguǒ","píngguò","pínggǔo"],"correct":0},{"say":"不喝","options":["bú hē","bù hē"],"correct":1},{"say":"我们去饭店","options":["wǒmen huí fàndiàn","wǒmen qù fàndiàn"],"correct":1}]}'),
  ('hsk1-09-6', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🍚","options":["米饭","菜","水"],"correct":0},{"emoji":"🍵","options":["水","茶","杯子"],"correct":1},{"emoji":"🍎","options":["水果","苹果","饭店"],"correct":1},{"emoji":"🥛","options":["饭店","菜","杯子"],"correct":2}]}'),
