  ('hsk1-09-6', 5, 'quiz', '{"title":"Экзаменационные вопросы","qs":[{"q":"Как сказать «Я пью чай»?","options":["我吃茶。","我茶喝。","我喝茶。"],"correct":2},{"q":"Как спросить «Что ты ешь?»","options":["你吃什么？","你吃什么吗？","什么你吃？"],"correct":0},{"q":"Как читается 不吃?","options":["bú chī","bù chī","bǔ chī"],"correct":1},{"q":"Воду «едят» с глаголом 吃.","tf":false},{"q":"Как сказать «чашка чая»?","options":["一个茶","一杯茶","杯一茶"],"correct":1},{"q":"Что значит 饭店?","options":["ресторан, отель","яблоко","стакан"],"correct":0},{"q":"和 соединяет предметы, например 米饭和菜.","tf":true},{"q":"Как ответить «нет» на 你喝茶吗？","options":["没有。","不是。","不喝。"],"correct":2},{"q":"Какой ключ у 吃?","options":["女","口","亻"],"correct":1},{"q":"Как сказать «Мы идём в ресторан»?","options":["我们去饭店。","我们饭店去。","我们回饭店。"],"correct":0}]}'),
  ('hsk1-09-6', 6, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","吃","米饭"],"hint":"«Я ем рис.»"},{"answer":["我","喝","水"],"hint":"«Я пью воду.»"},{"answer":["你","喝","什么"],"hint":"«Что ты пьёшь?»"},{"answer":["我","吃","一个","苹果"],"hint":"«Я ем яблоко.»"}]}'),
  ('hsk1-09-6', 7, 'game', '{"type":"bughunt","title":"Найдите ошибку","cases":[{"buggyText":"我吃水。","context":"«Я пью воду»","options":["我水喝。","我喝水。","喝我水。"],"correct":1},{"buggyText":"你吃什么吗？","context":"«Что ты ешь?»","options":["你吃什么？","你吃什么吗？","什么吃你？"],"correct":0},{"buggyText":"我喝一个茶。","context":"«Я пью чашку чая»","options":["我喝一茶杯。","我杯一喝茶。","我喝一杯茶。"],"correct":2}]}'),
  ('hsk1-09-6', 8, 'game', '{"type":"chatsim","title":"Мини-чат","messages":[{"speaker":"Официант","text":"你喝什么？","pinyin":"Nǐ hē shénme?","translation":"Что вы будете пить?","options":["我吃茶。","我茶喝。","我喝茶。"],"correct":2},{"speaker":"Официант","text":"你吃什么？","pinyin":"Nǐ chī shénme?","translation":"Что вы будете есть?","options":["我吃米饭和菜。","我喝米饭。","我吃喝菜。"],"correct":0}]}'),
