  ('hsk1-09-6', 10, 'recall', '{"words":[{"hanzi":"吃","pinyin":"chī","m":"есть"},{"hanzi":"喝","pinyin":"hē","m":"пить"},{"hanzi":"米饭","pinyin":"mǐfàn","m":"рис"},{"hanzi":"菜","pinyin":"cài","m":"блюдо"},{"hanzi":"水","pinyin":"shuǐ","m":"вода"},{"hanzi":"茶","pinyin":"chá","m":"чай"},{"hanzi":"苹果","pinyin":"píngguǒ","m":"яблоко"},{"hanzi":"水果","pinyin":"shuǐguǒ","m":"фрукты"},{"hanzi":"饭店","pinyin":"fàndiàn","m":"ресторан"},{"hanzi":"杯子","pinyin":"bēizi","m":"стакан"}],"tf":[{"zh":"我吃水。","py":"wǒ chī shuǐ.","m":"Я пью воду.","ok":false,"explain":"Воду пьют: 我喝水."},{"zh":"我喝一杯茶。","py":"wǒ hē yì bēi chá.","m":"Я пью чашку чая.","ok":true}],"sentences":[{"zh":"我吃米饭和菜。","tokens":["我","吃","米饭","和","菜"],"m":"Я ем рис и овощи."},{"zh":"你喝什么？","tokens":["你","喝","什么"],"m":"Что ты пьёшь?"},{"zh":"我喝一杯茶。","tokens":["我","喝","一杯","茶"],"m":"Я пью чашку чая."}]}'),
  ('hsk1-10-1', 1, 'fact', '{"emoji":"💖","title":"Сердце потерялось","text":"В традиционном 愛 «любовь» посередине есть 心 «сердце». В упрощённом 爱 сердце убрали, и по этому поводу китайцы до сих пор шутят: «любовь без сердца». Знак 想 «хотеть, думать» зато сохранил 心 внизу: мысль живёт в сердце. А 请 qǐng — слово вежливости, как «пожалуйста» перед просьбой."}'),
  ('hsk1-10-1', 2, 'words', '{"title":"Четыре слова чувств","items":[{"hanzi":"请","pinyin":"qǐng","m":"просить, пожалуйста","emoji":"🙏","ex":{"zh":"请喝茶。","py":"Qǐng hē chá.","m":"Пожалуйста, выпейте чаю."}},{"hanzi":"想","pinyin":"xiǎng","m":"хотеть, думать","emoji":"💭","ex":{"zh":"我想吃米饭。","py":"Wǒ xiǎng chī mǐfàn.","m":"Я хочу рис."}},{"hanzi":"喜欢","pinyin":"xǐhuan","m":"любить, нравиться","emoji":"😍","ex":{"zh":"我喜欢茶。","py":"Wǒ xǐhuan chá.","m":"Я люблю чай."}},{"hanzi":"爱","pinyin":"ài","m":"любить (сильно)","emoji":"❤️","ex":{"zh":"我爱妈妈。","py":"Wǒ ài māma.","m":"Я люблю маму."}}]}'),
  ('hsk1-10-1', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🙏","options":["想","喜欢","请"],"correct":2},{"emoji":"💭","options":["想","爱","请"],"correct":0},{"emoji":"😍","options":["请","喜欢","爱"],"correct":1},{"emoji":"❤️","options":["爱","想","请"],"correct":0}]}'),
  ('hsk1-10-1', 4, 'theory', '{"title":"喜欢 или 爱?","blocks":[{"t":"table","head":["Слово","Сила","Пример"],"rows":[["喜欢 xǐhuan","нравится, люблю (вещи, занятия)","我喜欢茶。"],["爱 ài","люблю (людей, родину)","我爱妈妈。"],["想 xiǎng","хочу (что-то сделать)","我想喝水。"]]},{"t":"p","text":"喜欢 безопасно: им говорят о еде, фильмах, людях. 爱 серьёзнее. 想 ставят перед глаголом: 想吃, 想喝."},{"t":"tip","text":"请 ставят в начале просьбы: 请喝茶 «Пожалуйста, пейте чай»."}]}'),
  ('hsk1-10-1', 5, 'quiz', '{"title":"Мини-тест: чувства","qs":[{"q":"Как сказать «Я хочу есть рис»?","options":["我想吃米饭。","我吃想米饭。","想我吃米饭。"],"correct":0},{"q":"爱 используют для самых тёплых чувств к людям.","tf":true},{"q":"Какое слово ставят перед просьбой?","options":["爱","喜欢","请"],"correct":2}]}'),
  ('hsk1-10-1', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["请","пожалуйста"],["想","хотеть"],["喜欢","любить, нравиться"],["爱","любить (сильно)"],["我想喝茶","Я хочу чай"]]}'),
  ('hsk1-10-1', 7, 'game', '{"type":"listen","title":"Слушаем: чувства и просьбы","items":[{"say":"请","options":["qìng","qíng","qǐng"],"correct":2},{"say":"想","options":["xiǎng","xiāng","xiàng"],"correct":0},{"say":"喜欢","options":["xǐhuan","xìhuan","xíhuan"],"correct":0},{"say":"爱","options":["ǎi","ài","āi"],"correct":1},{"say":"我想吃米饭","options":["wǒ xiǎng chī mǐfàn","wǒ xǐhuan chī mǐfàn"],"correct":0}]}'),
  ('hsk1-10-1', 8, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["我","想","喝","茶"],"hint":"«Я хочу чай.»"},{"answer":["我","喜欢","苹果"],"hint":"«Я люблю яблоки.»"},{"answer":["我","爱","妈妈"],"hint":"«Я люблю маму.»"}]}'),
  ('hsk1-10-1', 9, 'write', '{"title":"Пропись: чувства","items":[{"hanzi":"想","pinyin":"xiǎng","m":"хотеть","hint":"сверху 相, внизу 心"},{"hanzi":"爱","pinyin":"ài","m":"любить","hint":"сверху 爫, внизу 友"},{"hanzi":"请","pinyin":"qǐng","m":"просить","hint":"слева 讠, справа 青"}]}'),
  ('hsk1-10-1', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 请?","options":["любить","пожалуйста, просить","хотеть"],"correct":1},{"q":"Как читается 喜欢?","options":["xíhuan","xǐhuan","xìhuan"],"correct":1},{"q":"Как сказать «Я люблю маму»?","options":["我爱妈妈。","我喜欢爱妈妈。","妈妈我爱是。"],"correct":0},{"q":"想 ставится перед глаголом.","tf":true},{"q":"Какой ключ в знаке 想 внизу?","options":["口","女","心"],"correct":2}]}'),
  ('hsk1-10-2', 1, 'fact', '{"emoji":"🧩","title":"Три маленьких помощника","text":"Частица 呢 сокращает вопрос: вместо «А ты что будешь?» хватает 你呢？ Слово 都 «все» ставится перед глаголом и делает фразу общей. А 太 «слишком» вместе с 了 даёт эмоцию: 太好了！ «Как здорово!»"}'),
  ('hsk1-10-2', 2, 'words', '{"title":"Три маленьких слова","items":[{"hanzi":"呢","pinyin":"ne","m":"а ты? а как насчёт…","emoji":"🔄","ex":{"zh":"我喝茶，你呢？","py":"Wǒ hē chá, nǐ ne?","m":"Я пью чай, а ты?"}},{"hanzi":"都","pinyin":"dōu","m":"все, всё","emoji":"👥","ex":{"zh":"我们都喝茶。","py":"Wǒmen dōu hē chá.","m":"Мы все пьём чай."}},{"hanzi":"太","pinyin":"tài","m":"слишком, очень","emoji":"💥","ex":{"zh":"太好了！","py":"Tài hǎo le!","m":"Как здорово!"}}]}'),
  ('hsk1-10-2', 3, 'theory', '{"title":"Частица 呢: «а ты?»","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["我吃米饭，你呢？","Я ем рис, а ты?"],["我很好，你呢？","У меня всё хорошо, а у тебя?"],["他呢？","А он?"]]},{"t":"p","text":"呢 ставится в конце и повторяет предыдущую тему вопроса. Без исходного вопроса его не используют."}]}'),
  ('hsk1-10-2', 4, 'game', '{"type":"build","title":"Соберите фразу с 呢","items":[{"answer":["我","喝","茶","，","你","呢"],"hint":"«Я пью чай, а ты?»"},{"answer":["我","很","好","，","你","呢"],"hint":"«Я в порядке, а ты?»"},{"answer":["他","呢"],"hint":"«А он?»"}]}'),
  ('hsk1-10-2', 5, 'quiz', '{"title":"Мини-тест: 呢 и 都","qs":[{"q":"Как спросить «А ты?» после своей реплики?","options":["你吗？","你呢？","你什么？"],"correct":1},{"q":"呢 произносится без тона.","tf":true},{"q":"Где стоит 都?","options":["после глагола","в конце фразы","перед глаголом"],"correct":2}]}'),
  ('hsk1-10-2', 6, 'theory', '{"title":"都 «все» и 太 «слишком»","blocks":[{"t":"table","head":["Фраза","Перевод"],"rows":[["我们都是学生。","Мы все студенты."],["他们都喝茶。","Они все пьют чай."],["太多了！","Слишком много!"],["太好了！","Как здорово!"]]},{"t":"p","text":"都 ставится перед глаголом и после подлежащего. 太…了 — шаблон: 太 перед прилагательным, 了 в конце."},{"t":"tip","text":"Не говорите 太好 без 了 в таких восклицаниях: звучит неполно."}]}'),
  ('hsk1-10-2', 7, 'game', '{"type":"listen","title":"Слушаем: 呢, 都, 太","items":[{"say":"你呢","options":["nǐ ne","nǐ ma"],"correct":0},{"say":"我们都喝茶","options":["wǒmen dōu hē chá","wǒmen dōu chī chá"],"correct":0},{"say":"太好了","options":["tài hǎo le","tǎi hǎo le"],"correct":0},{"say":"太多了","options":["tài shǎo le","tài duō le"],"correct":1},{"say":"都","options":["dǒu","dōu","dóu"],"correct":1}]}'),
  ('hsk1-10-2', 8, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["呢","а ты?"],["都","все"],["太","слишком"],["太好了","как здорово"],["我们都喝茶","мы все пьём чай"]]}'),
  ('hsk1-10-2', 9, 'game', '{"type":"bughunt","title":"Китайский детектив: 呢, 都, 太","cases":[{"buggyText":"我们喝都茶。","context":"«Мы все пьём чай»","options":["我们都喝茶。","都我们喝茶。","我们喝茶都。"],"correct":0,"explain":"都 перед глаголом."},{"buggyText":"太好。","context":"«Как здорово!»","options":["太好吗！","太好了！","太是好！"],"correct":1},{"buggyText":"我喝茶，你吗？","context":"«Я пью чай, а ты?»","options":["我喝茶，你什么？","我喝茶，你好？","我喝茶，你呢？"],"correct":2}]}'),
  ('hsk1-10-2', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Что значит 都?","options":["все","слишком","а ты"],"correct":0},{"q":"Как сказать «Мы все студенты»?","options":["我们是都学生。","我们都是学生。","都我们是学生。"],"correct":1},{"q":"太好了 значит «Как здорово!»","tf":true},{"q":"Как читается 太?","options":["tài","tāi","tǎi"],"correct":0},{"q":"Для чего служит 呢?","options":["для вопроса «а ты?»","для отрицания","для числа"],"correct":0}]}'),
  ('hsk1-10-3', 1, 'fact', '{"emoji":"🔎","title":"Слово «как» в двух ролях","text":"Китайцы различают «как это?» и «каким образом?». 怎么样 zěnmeyàng спрашивает про качество («как тебе это?»), а 怎么 zěnme — про способ («как это сделать, сказать?»). И ещё одно полезное слово: 一点儿 yìdiǎnr «немного»: 我会说一点儿汉语."}'),
  ('hsk1-10-3', 2, 'words', '{"title":"Три слова","items":[{"hanzi":"怎么样","pinyin":"zěnmeyàng","m":"как, каково","emoji":"❓","ex":{"zh":"这个菜怎么样？","py":"Zhège cài zěnmeyàng?","m":"Как это блюдо?"}},{"hanzi":"怎么","pinyin":"zěnme","m":"как (каким образом)","emoji":"🛠️","ex":{"zh":"汉语怎么说？","py":"Hànyǔ zěnme shuō?","m":"Как это сказать по-китайски?"}},{"hanzi":"一点儿","pinyin":"yìdiǎnr","m":"немного","emoji":"🤏","ex":{"zh":"我会说一点儿汉语。","py":"Wǒ huì shuō yìdiǎnr Hànyǔ.","m":"Я говорю немного по-китайски."}}]}'),
  ('hsk1-10-3', 3, 'game', '{"type":"listen","title":"Слушаем: как?","items":[{"say":"怎么样","options":["zěnmeyàng","zěnmeyǎng","zénmeyàng"],"correct":0},{"say":"怎么","options":["zénme","zěnme","zèmne"],"correct":1},{"say":"一点儿","options":["yìdiǎnr","yīdiǎnr","yǐdiǎnr"],"correct":0,"explain":"Перед 3 тоном 一 читается yì."},{"say":"汉语怎么说","options":["Hànyǔ zěnme shuō","Hànyǔ zěnmeyàng shuō"],"correct":0},{"say":"这个菜怎么样","options":["zhège cài zěnmeyàng","zhège cài zěnme shuō"],"correct":0}]}'),
  ('hsk1-10-3', 4, 'game', '{"type":"tone_visualizer","initialTone":3,"title":"Тренажёр голоса: повторите «zěn» (3 тон)"}'),
  ('hsk1-10-3', 5, 'theory', '{"title":"怎么样 и 怎么","blocks":[{"t":"table","head":["Слово","О чём спрашивает","Пример"],"rows":[["怎么样","качество, оценка","你好吗？ → 你怎么样？"],["怎么","способ действия","怎么说？ «Как сказать?»"]]},{"t":"p","text":"怎么样 часто ставится в конце: 这个菜怎么样？ А 怎么 перед глаголом: 汉语怎么说？ 怎么写？"},{"t":"tip","text":"一点儿 стоит перед существительным или в конце фразы: 吃一点儿, 喝一点儿水."}]}'),
  ('hsk1-10-3', 6, 'game', '{"type":"match","title":"Слово и смысл","pairs":[["怎么样","как, каково"],["怎么","как (способ)"],["一点儿","немного"],["汉语怎么说","как сказать по-китайски"],["我会说一点儿","я говорю немного"]]}'),
  ('hsk1-10-3', 7, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🤏","options":["一点儿","怎么","太"],"correct":0},{"emoji":"🛠️","options":["怎么样","怎么","一点儿"],"correct":1},{"emoji":"❓","options":["怎么","一点儿","怎么样"],"correct":2}]}'),
  ('hsk1-10-3', 8, 'game', '{"type":"chatsim","title":"WeChat: как сказать?","messages":[{"speaker":"Друг","text":"这个菜怎么样？","pinyin":"Zhège cài zěnmeyàng?","translation":"Как тебе это блюдо?","options":["很好，太好了！","我怎么样。","很是菜。"],"correct":0},{"speaker":"Друг","text":"你会说汉语吗？","pinyin":"Nǐ huì shuō Hànyǔ ma?","translation":"Ты говоришь по-китайски?","options":["会，我会说一点儿。","不是，我汉语。","我怎么说。"],"correct":0},{"speaker":"Друг","text":"「谢谢」汉语怎么说？","pinyin":"“Thanks” Hànyǔ zěnme shuō?","translation":"Как сказать «спасибо» по-китайски?","options":["谢谢。","怎么样。","不客气。"],"correct":0,"explain":"Ответ — само слово: 谢谢."}]}'),
  ('hsk1-10-3', 9, 'game', '{"type":"build","title":"Соберите фразу","items":[{"answer":["这个","菜","怎么样"],"hint":"«Как тебе это блюдо?»"},{"answer":["汉语","怎么","说"],"hint":"«Как сказать по-китайски?»"},{"answer":["我","会","说","一点儿","汉语"],"hint":"«Я говорю немного по-китайски.»"}]}'),
  ('hsk1-10-3', 10, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как спросить «Как тебе это блюдо?»","options":["这个菜怎么？","这个菜怎么样？","这个菜怎么吗？"],"correct":1},{"q":"Как читается 一点儿?","options":["yìdiǎnr","yīdiǎnr","yǐdiǎnr"],"correct":0},{"q":"怎么 спрашивает про способ действия.","tf":true},{"q":"Как сказать «немного»?","options":["很","太","一点儿"],"correct":2},{"q":"Какая фраза значит «Как сказать по-китайски?»","options":["汉语怎么说？","怎么汉语说？","汉语说怎么？"],"correct":0}]}'),
  ('hsk1-10-4', 1, 'fact', '{"emoji":"🍜","title":"Как заказывают в Китае","text":"В ресторане меню читают всем столом, а заказ делает тот, кто «хозяин». Сегодня у нас Анна и Ли Мин, а у стола стоит официант."}'),
  ('hsk1-10-4', 2, 'text', '{"title":"В ресторане","lines":[{"zh":"服务员：你们好！你们想吃什么？","py":"Fúwùyuán: Nǐmen hǎo! Nǐmen xiǎng chī shénme?","m":"Официант: Здравствуйте! Что вы хотите?"},{"zh":"李明：我想吃米饭和菜。安娜，你呢？","py":"Lǐ Míng: Wǒ xiǎng chī mǐfàn hé cài. Ānnà, nǐ ne?","m":"Ли Мин: Я хочу рис и овощи. Анна, а ты?"},{"zh":"安娜：我想吃一点儿菜。","py":"Ānnà: Wǒ xiǎng chī yìdiǎnr cài.","m":"Анна: Я хочу немного овощей."},{"zh":"服务员：你们想喝什么？","py":"Fúwùyuán: Nǐmen xiǎng hē shénme?","m":"Официант: Что хотите пить?"},{"zh":"李明：我们都想喝茶。","py":"Lǐ Míng: Wǒmen dōu xiǎng hē chá.","m":"Ли Мин: Мы оба хотим чай."},{"zh":"安娜：这个菜怎么样？","py":"Ānnà: Zhège cài zěnmeyàng?","m":"Анна: Как это блюдо?"},{"zh":"服务员：很好。","py":"Fúwùyuán: Hěn hǎo.","m":"Официант: Очень хорошее."},{"zh":"安娜：太好了！谢谢！","py":"Ānnà: Tài hǎo le! Xièxie!","m":"Анна: Как здорово! Спасибо!"}],"qs":[{"q":"Что хочет Ли Мин?","options":["чай и яблоко","рис и овощи","только воду"],"correct":1},{"q":"Что хочет Анна?","options":["немного овощей","много риса","яблоко"],"correct":0},{"q":"Анна и Ли Мин хотят разные напитки.","tf":false,"explain":"Они оба хотят чай."},{"q":"Вставьте слово: 我们___想喝茶。","options":["太","也","都"],"correct":2},{"q":"Официант говорит, что блюдо очень хорошее.","tf":true},{"q":"Что значит 你呢？","options":["а ты?","ты хочешь?","кто ты?"],"correct":0},{"q":"Какое восклицание произносит Анна?","options":["太多了","太好了","不客气"],"correct":1}]}'),
  ('hsk1-10-4', 3, 'game', '{"type":"match","title":"Реплика и смысл","pairs":[["你们想吃什么？","Что вы хотите?"],["你呢？","А ты?"],["我们都想喝茶","Мы оба хотим чай"],["这个菜怎么样？","Как это блюдо?"],["太好了","Как здорово"]]}'),
  ('hsk1-10-4', 4, 'game', '{"type":"listen","title":"Слышим реплики","items":[{"say":"你们想吃什么","options":["nǐmen xiǎng chī shénme","nǐmen xiǎng hē shénme"],"correct":0},{"say":"我想吃一点儿菜","options":["wǒ xiǎng chī yìdiǎnr cài","wǒ xiǎng hē yìdiǎnr cài"],"correct":0},{"say":"我们都想喝茶","options":["wǒmen dōu xiǎng chī chá","wǒmen dōu xiǎng hē chá"],"correct":1},{"say":"太好了","options":["tài hǎo le","tài duō le"],"correct":0}]}'),
  ('hsk1-10-4', 5, 'game', '{"type":"bughunt","title":"Китайский детектив: в ресторане","cases":[{"buggyText":"我们想都喝茶。","context":"«Мы оба хотим чай»","options":["我们都想喝茶。","都我们想喝茶。","我们想喝茶都。"],"correct":0},{"buggyText":"你吃什么呢吗？","context":"«А ты что хочешь?»","options":["你呢吃什么？","你想吃什么？","吃什么你吗？"],"correct":1},{"buggyText":"太好！","context":"«Как здорово!»","options":["太好吗！","太好是！","太好了！"],"correct":2}]}'),
  ('hsk1-10-4', 6, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как сказать «Я хочу рис»?","options":["我想吃米饭。","我想喝米饭。","想我米饭。"],"correct":0},{"q":"Как читается 想?","options":["xiàng","xiǎng","xiāng"],"correct":1},{"q":"В диалоге Анна заказывает много риса.","tf":false},{"q":"Как сказать «Мы оба хотим чай»?","options":["我们想都喝茶。","都我们想喝茶。","我们都想喝茶。"],"correct":2}]}'),
  ('hsk1-10-5', 1, 'fact', '{"emoji":"🥢","title":"Расскажите о вкусах","text":"Сегодня вы рассказываете, что вам нравится, и спрашиваете у собеседника «а ты?». Слова глав 1–10."}'),
  ('hsk1-10-5', 2, 'game', '{"type":"radical_puzzle","hanzi":"想","correctRadicals":["相","心"],"title":"Пазл: соберите 想"}'),
  ('hsk1-10-5', 3, 'game', '{"type":"radical_build","title":"Сборка знаков","items":[{"targetHanzi":"请","radicals":["讠","青","亻"],"correctOrder":["讠","青"],"explain":"Слева «речь» 讠, справа 青."},{"targetHanzi":"爱","radicals":["爫","友","心"],"correctOrder":["爫","友"],"explain":"Сверху 爫, снизу 友."},{"targetHanzi":"喜","radicals":["十","口","豆"],"correctOrder":["十","口","豆"],"explain":"Сверху 十, потом 口, снизу 豆."}]}'),
  ('hsk1-10-5', 4, 'game', '{"type":"build","title":"Мастерская вкусов","items":[{"target":"(Любимое)","answer":["我","喜欢","茶"],"hint":"«Я люблю чай.»"},{"target":"(Любимое)","answer":["我","喜欢","吃","苹果"],"hint":"«Я люблю есть яблоки.»"},{"target":"(Вопрос)","answer":["你","喜欢","什么","菜"],"hint":"«Какие блюда ты любишь?»"},{"target":"(Ответ)","answer":["我们","都","喜欢","米饭"],"hint":"«Мы все любим рис.»"}]}'),
  ('hsk1-10-5', 5, 'theory', '{"title":"Алгоритм разговора о вкусах","blocks":[{"t":"table","head":["Шаг","Фраза"],"rows":[["1. Вопрос","你喜欢什么？"],["2. Ответ","我喜欢…"],["3. А ты?","你呢？"],["4. Эмоция","太好了！"]]}]}'),
  ('hsk1-10-5', 6, 'game', '{"type":"chatsim","title":"WeChat: вкусы","messages":[{"speaker":"Друг","text":"你喜欢什么菜？","pinyin":"Nǐ xǐhuan shénme cài?","translation":"Какие блюда ты любишь?","options":["我喜欢米饭。","我喜欢什么。","我是菜。"],"correct":0},{"speaker":"Друг","text":"我也喜欢米饭！你喝茶吗？","pinyin":"Wǒ yě xǐhuan mǐfàn! Nǐ hē chá ma?","translation":"Я тоже люблю рис! Ты пьёшь чай? (也 «тоже» — новое слово)","options":["不喝，我喝水。","不吃，我喝茶。","不是，我水。"],"correct":0},{"speaker":"Друг","text":"太好了！我们去饭店吧！","pinyin":"Tài hǎo le! Wǒmen qù fàndiàn ba!","translation":"Как здорово! Пойдём в ресторан! (吧 — новая частица)","options":["好，我们去！","好，我去不。","不好，我吃。"],"correct":0}]}'),
  ('hsk1-10-5', 7, 'game', '{"type":"match","title":"Знак и его части","pairs":[["相 + 心","想"],["讠 + 青","请"],["爫 + 友","爱"],["十 + 口 + 豆","喜"]]}'),
  ('hsk1-10-5', 8, 'write', '{"title":"Пропись","items":[{"hanzi":"太","pinyin":"tài","m":"слишком","hint":"大 и точка внизу"},{"hanzi":"都","pinyin":"dōu","m":"все","hint":"слева 者, справа 阝"},{"hanzi":"喜","pinyin":"xǐ","m":"радость","hint":"сверху 士, потом 口, снизу 豆"}]}'),
  ('hsk1-10-5', 9, 'quiz', '{"title":"Итог урока","qs":[{"q":"Как спросить «А ты?» про вкус?","options":["你呢？","你吗？","你什么？"],"correct":0},{"q":"Как сказать «Мы все любим рис»?","options":["我们喜欢都米饭。","我们都喜欢米饭。","都我们喜欢米饭。"],"correct":1},{"q":"喜欢 безопаснее 爱 в обычном разговоре.","tf":true}]}'),
  ('hsk1-10-6', 1, 'fact', '{"emoji":"🏁","title":"Экзамен главы 10","text":"请, 想, 喜欢, 爱, 呢, 都, 太, 怎么样, 怎么, 一点儿 и разговор в ресторане."}'),
