  ('hsk1-10-6', 3, 'game', '{"type":"emoji","big":true,"title":"Эмодзи → слово","items":[{"emoji":"🙏","options":["请","爱","想"],"correct":0},{"emoji":"💭","options":["喜欢","想","请"],"correct":1},{"emoji":"❤️","options":["想","请","爱"],"correct":2},{"emoji":"💥","options":["太","都","呢"],"correct":0}]}'),
  ('hsk1-10-6', 4, 'game', '{"type":"match","title":"Слова главы","pairs":[["请","пожалуйста"],["想","хотеть"],["喜欢","нравиться"],["爱","любить"],["呢","а ты?"],["都","все"],["太","слишком"],["怎么样","каково"],["怎么","как (способ)"],["一点儿","немного"]]}'),
  ('hsk1-10-6', 5, 'quiz', '{"title":"Экзаменационные вопросы","qs":[{"q":"Как сказать «Я хочу чай»?","options":["我想茶。","我喝想茶。","我想喝茶。"],"correct":2},{"q":"Как спросить «А ты?»","options":["你呢？","你吗？","你什么？"],"correct":0},{"q":"Где стоит 都?","options":["перед глаголом","после глагола","в начале всего предложения"],"correct":0},{"q":"爱 слабее, чем 喜欢.","tf":false},{"q":"Как сказать «Как это блюдо?»","options":["这个菜怎么？","这个菜怎么样？","怎么这个菜？"],"correct":1},{"q":"Как читается 一点儿?","options":["yīdiǎnr","yìdiǎnr","yǐdiǎnr"],"correct":1},{"q":"太好了 — выражение радости.","tf":true},{"q":"Как сказать «Мы все любим чай»?","options":["我们都喜欢茶。","我们喜欢都茶。","都我们喜欢茶。"],"correct":0},{"q":"Что значит 请?","options":["любить","хотеть","пожалуйста"],"correct":2},{"q":"Как спросить «Как сказать по-китайски?»","options":["怎么汉语说？","汉语怎么说？","汉语说怎么？"],"correct":1}]}'),
