  ('hsk1-10-6', 7, 'game', '{"type":"bughunt","title":"Найдите ошибку","cases":[{"buggyText":"我想吃喝茶。","context":"«Я хочу чай»","options":["我想喝茶。","想我喝茶。","我喝想茶。"],"correct":0},{"buggyText":"太好。","context":"«Как здорово!»","options":["太好吗！","太好是！","太好了！"],"correct":2},{"buggyText":"我们喝都茶。","context":"«Мы все пьём чай»","options":["都我们喝茶。","我们都喝茶。","我们喝茶都。"],"correct":1}]}'),
  ('hsk1-10-6', 8, 'game', '{"type":"chatsim","title":"Мини-чат","messages":[{"speaker":"Официант","text":"你们想吃什么？","pinyin":"Nǐmen xiǎng chī shénme?","translation":"Что вы хотите?","options":["我们想吃米饭。","我们吃想米饭。","我们是米饭。"],"correct":0},{"speaker":"Официант","text":"你们想喝什么？","pinyin":"Nǐmen xiǎng hē shénme?","translation":"Что хотите пить?","options":["我们吃茶。","我们都想喝茶。","都我们茶。"],"correct":1}]}'),
