  ('hsk1-10-6', 10, 'recall', '{"words":[{"hanzi":"请","pinyin":"qǐng","m":"пожалуйста"},{"hanzi":"想","pinyin":"xiǎng","m":"хотеть"},{"hanzi":"喜欢","pinyin":"xǐhuan","m":"нравиться"},{"hanzi":"爱","pinyin":"ài","m":"любить"},{"hanzi":"呢","pinyin":"ne","m":"а ты?"},{"hanzi":"都","pinyin":"dōu","m":"все"},{"hanzi":"太","pinyin":"tài","m":"слишком"},{"hanzi":"怎么样","pinyin":"zěnmeyàng","m":"каково"},{"hanzi":"怎么","pinyin":"zěnme","m":"как"},{"hanzi":"一点儿","pinyin":"yìdiǎnr","m":"немного"}],"tf":[{"zh":"我们喝都茶。","py":"wǒmen hē dōu chá.","m":"Мы все пьём чай.","ok":false,"explain":"都 перед глаголом: 我们都喝茶."},{"zh":"太好了！","py":"tài hǎo le!","m":"Как здорово!","ok":true}],"sentences":[{"zh":"我想喝茶。","tokens":["我","想","喝","茶"],"m":"Я хочу чай."},{"zh":"我们都喜欢米饭。","tokens":["我们","都","喜欢","米饭"],"m":"Мы все любим рис."},{"zh":"汉语怎么说？","tokens":["汉语","怎么","说"],"m":"Как сказать по-китайски?"}]}'),
